insert into public.dataset_notes (key, body) values
  ('species.note', 'Hominin species and populations. Time ranges summarise the known fossil, archaeological or genetic record and are approximate; first and last appearances in the record are not the same as origin and extinction. Evolution was branching: several of these species lived at the same time. Review with a domain specialist before publishing.'),
  ('migrations.disclaimer', 'Demonstration dataset. Route paths, waypoint years, group structure and pacing are ILLUSTRATIVE visual reconstructions. Site dates and the cited literature are the evidence layer; site coordinates are approximate. Citations should be reviewed by a domain specialist and the routes replaced with research-backed data before publication.'),
  ('populations.note', 'Population clusters show approximate, modelled presence of Homo sapiens in a region; they are not population counts. ''visualDensity'' is a rendering parameter only. Periods are approximate and the earliest-evidence years (''attestedYear'') are conservative summaries for orientation; review with a domain specialist before publishing. Where no attestedYear is given, or before it, presence is inferred.'),
  ('milestones.note', 'Milestones date the earliest known evidence at a specific place. That is not the same as the origin of a practice, and developments did not happen everywhere at once. Species are linked only where the evidence supports it; routes only where the evidence itself connects them. Review with a domain specialist before publishing.'),
  ('sources.note', 'Sources for species, sites and milestones added in the human-history expansion. Merged with the migration sources by the data loader.');
