insert into public.species (id, sort_order, name, scientific_name, genus, species_group, classification, taxonomy_note, older_bp, younger_bp, time_note, distribution, physical, technology, relationships, confidence, camera, focus_year) values
  ('homo-sapiens', 0, 'Homo sapiens', 'Homo sapiens', 'Homo', 'sapiens', 'Hominini · Homo · H. sapiens', 'Early African fossils such as Jebel Irhoud combine a modern face with a more elongated braincase; how to draw the boundary of the species in deep time is debated.', 315000, 0, 'Jebel Irhoud (~315,000 years ago, with a dating uncertainty of tens of thousands of years) is currently the oldest fossil evidence. The species'' origin may be older and likely involved populations across Africa.', 'Africa first; from roughly 70,000–50,000 years ago across Eurasia and Sahul, the Americas by at least ~15,000 years ago, and remote Pacific islands only within the last few thousand years.', 'A rounded (globular) braincase, a small face tucked under the forehead, small brow ridges, a chin and a comparatively light skeleton. Early members of the species show a mix of modern and older traits.', 'Middle Stone Age tool kits in Africa; later ornaments, pigments and abstract and figurative art, projectile weapons, sewn clothing and sea crossings. Farming, pottery, metallurgy, cities and writing appear only in the last ~20,000 years, at different times in different regions.', 'Shared ancestors with Neanderthals and Denisovans in the Middle Pleistocene. Genomes show interbreeding: most people outside Africa carry roughly 1–2% Neanderthal DNA, and some populations, especially in Oceania, also carry Denisovan ancestry.', 'high', '{"lat":8,"lng":30,"distance":3.4}'::jsonb, 100000),
  ('homo-neanderthalensis', 1, 'Neanderthals', 'Homo neanderthalensis', 'Homo', 'other', 'Hominini · Homo · H. neanderthalensis', 'Some researchers treat Neanderthals as a subspecies of Homo sapiens (H. sapiens neanderthalensis). The ~430,000-year-old Sima de los Huesos fossils belong to the Neanderthal lineage but are not ''classic'' Neanderthals.', 430000, 40000, 'Neanderthal-lineage features appear by ~430,000 years ago; classic Neanderthals are known from roughly 250,000 years ago. They disappear from the record across Europe around 41,000–39,000 years ago.', 'Europe and western Asia: from Iberia to the Levant, the Zagros, the Caucasus, and as far east as the Altai Mountains of Siberia.', 'Large braincases (on average as large as or larger than those of modern humans), long and low skulls, prominent brow ridges, large noses and stocky, muscular bodies, often discussed as adaptations to cold climates.', 'Middle Palaeolithic (Mousterian) stone tools made with prepared-core techniques, hafted tools, adhesives made from birch tar, controlled fire and hunting of large mammals. Claims of Neanderthal cave art and symbolism are debated.', 'Sister lineage to Denisovans; the two lineages separated from the line leading to Homo sapiens roughly 550,000–765,000 years ago. Neanderthals interbred with Homo sapiens and with Denisovans (a first-generation Neanderthal–Denisovan child is known from Denisova Cave).', 'high', '{"lat":44,"lng":18,"distance":3.2}'::jsonb, 60000),
  ('denisovans', 2, 'Denisovans', null, 'Homo', 'other', 'Hominini · Homo · (no formal species name)', 'Identified first from DNA in a finger bone from Denisova Cave (2010). Too few diagnostic fossils have been described to name the group formally; attributions of other East Asian fossils to Denisovans are an active research area.', 200000, 50000, 'Denisovans occupied Denisova Cave from roughly 200,000 to 50,000 years ago; the Xiahe mandible from the Tibetan Plateau is at least ~160,000 years old. Genetic evidence suggests populations lived elsewhere in Asia, and possibly later, but where is uncertain.', 'Known directly from the Altai Mountains (Siberia) and the Tibetan Plateau. Denisovan ancestry in present-day populations of Oceania, East and South Asia implies a much wider range.', 'Known only from a few bones and teeth: very large molars and a robust lower jaw. Overall body form is unknown.', 'Little can be attributed with confidence; Denisova Cave contains stone tools from several periods, and which group made which is debated.', 'Sister group to Neanderthals. Interbred with Neanderthals (Denisova 11, a first-generation hybrid) and with Homo sapiens.', 'medium', '{"lat":42,"lng":92,"distance":3.3}'::jsonb, 100000),
  ('homo-floresiensis', 3, 'Homo floresiensis', 'Homo floresiensis', 'Homo', 'other', 'Hominini · Homo · H. floresiensis', 'Its ancestry is debated: an early Homo erectus-like population that became smaller on the island, or a descendant of an even more primitive lineage.', 700000, 50000, 'Skeletal remains at Liang Bua date to ~100,000–60,000 years ago and stone tools there to ~50,000. Small hominin fossils at Mata Menge (~700,000 years ago) resemble H. floresiensis; stone tools show hominins on Flores by ~1 million years ago.', 'The island of Flores, Indonesia.', 'About 1.1 m tall with a very small brain (~400 cm³), long arms and large feet. Nicknamed ''the hobbit''.', 'Stone tools; the full range of its behaviour is unknown.', 'Lived at the same time as Homo sapiens, Neanderthals and Denisovans elsewhere; no evidence of contact.', 'medium', '{"lat":-8,"lng":120,"distance":2.6}'::jsonb, 80000),
  ('homo-luzonensis', 4, 'Homo luzonensis', 'Homo luzonensis', 'Homo', 'other', 'Hominini · Homo · H. luzonensis', 'Named in 2019 from teeth and hand and foot bones. Its ancestry is unknown; some features recall much older hominins.', 67000, 50000, 'The fossils have minimum ages of ~67,000 and ~50,000 years. Stone tools and a butchered rhinoceros show hominins on Luzon by ~709,000 years ago, but who made them is unknown.', 'The island of Luzon, Philippines.', 'Small teeth with a mix of primitive and modern traits; curved finger and toe bones suggest climbing.', 'Unknown from the fossil site itself; stone tools are known on Luzon from ~709,000 years ago.', 'Lived at the same time as Homo sapiens, Neanderthals, Denisovans and Homo floresiensis; its relationship to them is unknown.', 'medium', '{"lat":17,"lng":121.5,"distance":2.2}'::jsonb, 60000),
  ('homo-naledi', 5, 'Homo naledi', 'Homo naledi', 'Homo', 'other', 'Hominini · Homo · H. naledi', 'Known from a single cave system; its relationship to other Homo species is unresolved.', 335000, 236000, 'Fossils from the Rising Star cave system date to ~335,000–236,000 years ago, overlapping with early Homo sapiens in Africa.', 'Known only from the Rising Star cave system, South Africa; its real range is unknown.', 'A small brain (~465–610 cm³) combined with human-like hands and feet and curved fingers suited to climbing: a mosaic of old and new traits.', 'No stone tools have been securely associated. Claims that it deliberately placed its dead in the cave are debated.', 'A late-surviving small-brained lineage that overlapped in time with early Homo sapiens.', 'medium', '{"lat":-24,"lng":26,"distance":2.8}'::jsonb, 280000),
  ('homo-erectus', 6, 'Homo erectus', 'Homo erectus', 'Homo', 'other', 'Hominini · Homo · H. erectus', 'Early African specimens are sometimes called Homo ergaster; the Dmanisi fossils are usually assigned to H. erectus in a broad sense, though some researchers use separate names.', 1900000, 110000, 'From ~1.9 million years ago in Africa; at Dmanisi, Georgia, by ~1.8 million years ago; the youngest known fossils, at Ngandong (Java), date to ~117,000–108,000 years ago.', 'Africa, the Caucasus (Dmanisi), China and Java. Stone tools in China (~2.1 million years ago) show that hominins reached East Asia even earlier, made by an unknown species.', 'Body proportions close to those of modern humans, long legs and a larger brain than earlier Homo (roughly 550–1,250 cm³), with a long, low skull and thick brow ridges.', 'Acheulean handaxes appear in Africa ~1.76 million years ago and are generally linked to H. erectus; East Asian sites mostly have simpler core-and-flake tools. Some of the earliest evidence of fire use falls within its time range.', 'Long-lived and widespread; how it relates to later Homo lineages (including our own) is debated.', 'high', '{"lat":15,"lng":70,"distance":3.9}'::jsonb, 1500000),
  ('homo-habilis', 7, 'Homo habilis', 'Homo habilis', 'Homo', 'other', 'Hominini · Homo · H. habilis', 'Which fossils belong to H. habilis (and which to H. rudolfensis or other early Homo) is debated. The oldest fossil attributed to Homo (Ledi-Geraru, ~2.8 million years ago) is not assigned to this species.', 2400000, 1400000, 'Roughly 2.4–1.4 million years ago in East Africa.', 'East Africa (e.g. Olduvai Gorge, Koobi Fora).', 'A somewhat larger brain than australopiths, smaller teeth, but still long arms and a small body.', 'Often associated with Oldowan stone tools, but the earliest Oldowan tools are older than its fossils, and Paranthropus is also present at early Oldowan sites, so the toolmakers are not certain.', 'Coexisted with Paranthropus boisei and, later, Homo erectus.', 'medium', '{"lat":0,"lng":36,"distance":2.9}'::jsonb, 1900000),
  ('paranthropus-boisei', 8, 'Paranthropus boisei', 'Paranthropus boisei', 'Paranthropus', 'other', 'Hominini · Paranthropus · P. boisei (not genus Homo)', 'A ''robust australopith''. Some researchers include it in Australopithecus.', 2300000, 1200000, 'Roughly 2.3–1.2 million years ago.', 'East Africa (e.g. Olduvai Gorge, Lake Turkana, Konso).', 'Massive jaws and molars, a crest on top of the skull for large chewing muscles and a small brain.', 'Whether it made or used stone tools is debated; its teeth have been found alongside early Oldowan tools.', 'A side branch, not an ancestor of Homo. Lived alongside Homo habilis and Homo erectus for hundreds of thousands of years.', 'high', '{"lat":0,"lng":36,"distance":2.9}'::jsonb, 1800000),
  ('australopithecus-afarensis', 9, 'Australopithecus afarensis', 'Australopithecus afarensis', 'Australopithecus', 'other', 'Hominini · Australopithecus · A. afarensis (not genus Homo)', 'Not a member of the genus Homo. Whether it is directly ancestral to Homo is debated.', 3850000, 2950000, 'Roughly 3.85–2.95 million years ago; ''Lucy'' (Hadar) is ~3.2 million years old. The species is already present when this timeline begins.', 'East Africa (e.g. Hadar and Dikika in Ethiopia, Laetoli in Tanzania).', 'Walked upright on two legs (the Laetoli footprints are usually attributed to it) while keeping adaptations for climbing; small brain (~380–550 cm³).', 'No stone tools are directly associated with its fossils.', 'One of several hominins of its time; its relationship to later lineages, including Homo, is debated.', 'high', '{"lat":4,"lng":38,"distance":2.9}'::jsonb, 3200000);
