insert into public.archaeological_sites (id, sort_order, name, region, lat, lng, older_bp, younger_bp, description, details, confidence) values
  ('jebel-irhoud', 0, 'Jebel Irhoud', 'Morocco', 31.86, -8.87, 350000, 280000, 'Fossils dated ~315,000 years ago (±34,000), currently the earliest attributed to Homo sapiens.', null, 'medium'),
  ('omo-kibish', 1, 'Omo Kibish', 'Ethiopia', 5.4, 35.9, 233000, 195000, 'Omo I. Age estimates range from ~195,000 to a minimum of ~233,000 years depending on the study.', null, 'medium'),
  ('misliya', 2, 'Misliya Cave', 'Israel', 32.7, 34.97, 194000, 177000, 'A modern-human maxilla dated ~177,000–194,000 years ago, among the earliest sapiens evidence outside Africa.', null, 'medium'),
  ('herto', 3, 'Herto', 'Ethiopia', 10.3, 40.5, 160000, 154000, 'Crania from the Middle Awash dated ~154,000–160,000 years ago.', null, 'high'),
  ('skhul', 4, 'Skhul', 'Israel', 32.67, 34.97, 135000, 100000, 'Burials of early Homo sapiens at Mount Carmel, dated roughly 100,000–135,000 years ago.', null, 'medium'),
  ('qafzeh', 5, 'Qafzeh', 'Israel', 32.69, 35.32, 120000, 90000, 'Early Homo sapiens burials near Nazareth, dated roughly 90,000–120,000 years ago.', null, 'medium'),
  ('jwalapuram', 6, 'Jwalapuram', 'India', 15.33, 78.13, 80000, 70000, 'Stone tools from before and after the ~74,000-year-old Toba eruption; whether their makers were Homo sapiens is debated.', null, 'low'),
  ('tam-pa-ling', 7, 'Tam Pa Ling', 'Laos', 20.21, 103.41, 63000, 46000, 'Modern human skull dated to at least ~46,000 years ago.', null, 'medium'),
  ('grotte-mandrin', 8, 'Grotte Mandrin', 'France', 44.48, 4.77, 56000, 52000, 'Modern-human tooth and tools dated ~54,000 years ago; interpretation debated.', null, 'medium'),
  ('madjedbebe', 9, 'Madjedbebe', 'Australia', -12.5, 132.9, 65000, 50000, 'Occupation dated ~65,000 years ago by some, ~50,000 or less by others.', null, 'low'),
  ('bacho-kiro', 10, 'Bacho Kiro', 'Bulgaria', 42.95, 25.43, 46000, 44000, 'Among the earliest Homo sapiens in Europe, ~46,000–44,000 years ago.', null, 'high'),
  ('ortvale-klde', 11, 'Ortvale Klde', 'Georgia', 42.28, 43.22, 42000, 38000, 'Rockshelter recording Upper Palaeolithic occupation from ~42,000–38,000 years ago (approximate location).', null, 'medium'),
  ('lake-mungo', 12, 'Lake Mungo', 'Australia', -33.7, 143.1, 42000, 38000, 'Burials showing people in the Australian interior by ~42,000 years ago.', null, 'high'),
  ('yana-rhs', 13, 'Yana RHS', 'Siberia', 70.7, 135.4, 32000, 27000, 'Arctic Siberian site occupied ~32,000 years ago.', null, 'high'),
  ('dzudzuana', 14, 'Dzudzuana Cave', 'Georgia', 42.31, 43.27, 27000, 24000, 'Source of ~26,000-year-old Caucasus genomes (approximate location).', null, 'medium'),
  ('white-sands', 15, 'White Sands', 'New Mexico', 32.84, -106.35, 23000, 21000, 'Human footprints dated ~23,000–21,000 years ago; dating debated.', null, 'low'),
  ('monte-verde', 16, 'Monte Verde', 'Chile', -41.5, -73.2, 14600, 14200, 'Settlement occupied by ~14,500 years ago.', null, 'high'),
  ('hadar', 17, 'Hadar', 'Afar, Ethiopia', 11.1, 40.58, 3400000, 2950000, 'Australopithecus afarensis fossils, including ''Lucy'' (~3.2 million years ago).', 'One of the richest Pliocene hominin localities. Lucy (A.L. 288-1), found in 1974, preserves about 40% of a skeleton and shows upright walking combined with a small brain. A.L. 333 preserves remains of at least nine individuals.', 'high'),
  ('olduvai', 18, 'Olduvai Gorge', 'Tanzania', -2.99, 35.35, 2000000, 1200000, 'Fossils of Paranthropus boisei and Homo habilis (both ~1.8 million years ago), plus Oldowan and Acheulean tools.', 'Olduvai''s layered deposits record nearly two million years. The type specimens of Paranthropus boisei (OH 5, 1959) and Homo habilis (OH 7, 1964) come from the same period, a classic case of different hominins living side by side.', 'high'),
  ('kokiselei', 19, 'Kokiselei 4', 'West Turkana, Kenya', 4.05, 35.78, 1780000, 1740000, 'The oldest known Acheulean handaxes, ~1.76 million years ago. No hominin fossils at the site. Location approximate.', 'Large cutting tools shaped on both faces mark the beginning of the Acheulean. They are usually linked to Homo erectus because of their age and region, but no fossils were found with them.', 'high'),
  ('dmanisi', 20, 'Dmanisi', 'Kvemo Kartli, Georgia', 41.338, 44.344, 1850000, 1770000, 'The oldest hominin fossils known outside Africa (~1.85–1.78 million years ago): early Homo, not Homo sapiens.', 'Five skulls and other remains of early Homo, together with simple stone tools, lie beneath a medieval town in southern Georgia. They are usually assigned to Homo erectus in a broad sense. Their small brains (~550–775 cm³) and the large variation between individuals reshaped ideas about the first hominins to leave Africa. These people lived about 1.8 million years before Homo sapiens reached the Caucasus.', 'high'),
  ('rising-star', 21, 'Rising Star Cave', 'Gauteng, South Africa', -25.918, 27.711, 335000, 236000, 'More than 1,500 fossil elements of Homo naledi, ~335,000–236,000 years old.', null, 'high'),
  ('kebara', 22, 'Kebara Cave', 'Mount Carmel, Israel', 32.558, 34.937, 64000, 48000, 'Neanderthal occupation; the Kebara 2 skeleton (~60,000 years ago) preserves a hyoid bone.', null, 'high'),
  ('denisova-cave', 23, 'Denisova Cave', 'Altai Mountains, Russia', 51.397, 84.676, 200000, 50000, 'Where Denisovans were identified from DNA; also occupied by Neanderthals, and later by Homo sapiens.', 'A finger bone sequenced in 2010 revealed a previously unknown hominin group. The cave also yielded Denisova 11, the daughter of a Neanderthal mother and a Denisovan father, direct proof that the two groups met.', 'high'),
  ('baishiya-karst', 24, 'Baishiya Karst Cave', 'Tibetan Plateau, China', 35.45, 102.57, 160000, 60000, 'The Xiahe mandible (at least ~160,000 years old), identified as Denisovan by ancient proteins, at ~3,280 m altitude.', null, 'medium'),
  ('liang-bua', 25, 'Liang Bua', 'Flores, Indonesia', -8.534, 120.457, 100000, 50000, 'Skeletal remains of Homo floresiensis (~100,000–60,000 years ago) and stone tools to ~50,000 years ago.', null, 'high'),
  ('satsurblia', 26, 'Satsurblia Cave', 'Imereti, Georgia', 42.377, 42.597, 25500, 13000, 'Upper Palaeolithic cave occupied before and after the Last Glacial Maximum; a ~13,300-year-old human genome. Location approximate.', 'Satsurblia records hunter-gatherers in western Georgia around the coldest phase of the last Ice Age. The genome of a woman who lived ~13,300 years ago revealed a distinct ''Caucasus hunter-gatherer'' ancestry that split from other West Eurasian groups tens of thousands of years earlier and later contributed to many populations of Western Eurasia.', 'medium'),
  ('kotias-klde', 27, 'Kotias Klde', 'Imereti, Georgia', 42.29, 43.21, 10500, 9000, 'Mesolithic rockshelter; a ~9,700-year-old human genome showing Caucasus hunter-gatherer ancestry. Location approximate.', 'The Kotias Klde genome, together with Satsurblia, shows that the Caucasus hunter-gatherer population persisted in the region across several thousand years, from the late Ice Age into the Holocene.', 'medium'),
  ('gadachrili-gora', 28, 'Gadachrili Gora', 'Kvemo Kartli, Georgia', 41.43, 44.74, 8000, 7800, 'Early Neolithic village with chemical evidence of grape wine in pottery, ~6000–5800 BCE. Location approximate.', 'Residue analysis of pottery from Gadachrili Gora and nearby Shulaveris Gora (Shulaveri–Shomutepe culture) detected tartaric acid and related compounds, the chemical signature of grape wine, ~8,000 years ago. It is the earliest known chemical evidence of grape wine.', 'high'),
  ('jebel-faya', 29, 'Jebel Faya', 'Sharjah, UAE', 25.12, 55.85, 125000, 100000, 'Stone tools dated by luminescence to ~125,000–100,000 years ago. No fossils: the makers are inferred to be Homo sapiens.', null, 'medium'),
  ('al-wusta', 30, 'Al Wusta', 'Nefud Desert, Saudi Arabia', 28.4, 40.3, 95000, 86000, 'A Homo sapiens finger bone directly dated to ~88,000 years ago, beside an ancient lake.', null, 'high'),
  ('apidima', 31, 'Apidima Cave', 'Mani, Greece', 36.63, 22.38, 210000, 170000, 'Apidima 1 (>210,000 years) has been described as early Homo sapiens; Apidima 2 (>170,000) is Neanderthal-like. The attribution of Apidima 1 is disputed.', null, 'low'),
  ('lida-ajer', 32, 'Lida Ajer', 'Padang Highlands, Sumatra', -0.3, 100.4, 73000, 63000, 'Modern human teeth from a cave excavated in the 1880s, re-dated to ~73,000–63,000 years ago.', null, 'medium'),
  ('ust-ishim', 33, 'Ust''-Ishim', 'Irtysh River, western Siberia', 57.7, 71.2, 46000, 44000, 'A femur directly radiocarbon-dated to ~45,000 years ago; its genome belongs to a lineage with no living descendants.', null, 'high'),
  ('tianyuan', 34, 'Tianyuan Cave', 'Beijing, China', 39.65, 115.87, 42000, 39000, 'A ~40,000-year-old individual whose genome is related to present-day East Asians and Native Americans.', null, 'high'),
  ('nwya-devu', 35, 'Nwya Devu', 'Central Tibetan Plateau', 31.6, 90, 40000, 30000, 'Stone tools at ~4,600 m altitude dated by OSL to 40,000–30,000 years ago. No fossils; the makers are not identified.', null, 'medium'),
  ('taforalt', 36, 'Taforalt (Grotte des Pigeons)', 'Morocco', 34.81, -2.41, 15100, 13900, 'Iberomaurusian burials whose genomes are about two-thirds Near Eastern (Natufian-related) and one-third sub-Saharan African.', null, 'high'),
  ('mota-cave', 37, 'Mota Cave', 'Ethiopian Highlands', 6.6, 37.2, 4600, 4400, 'A ~4,500-year-old genome that predates the West Eurasian back-flow into East Africa.', null, 'high'),
  ('catalhoyuk', 38, 'Çatalhöyük', 'Konya Plain, Türkiye', 37.67, 32.83, 9400, 8000, 'Large Neolithic settlement on the Anatolian plateau, close to the source of Europe''s first farmers.', null, 'high'),
  ('goughs-cave', 39, 'Gough''s Cave', 'Cheddar, England', 51.28, -2.77, 14900, 14600, 'Magdalenian-associated humans recolonising Britain after the Last Glacial Maximum.', null, 'high'),
  ('villabruna', 40, 'Riparo Villabruna', 'Dolomites, Italy', 46.1, 11.9, 14200, 13900, 'Epigravettian burial whose genome names the ''Villabruna'' ancestry that spread across Europe from ~14,000 years ago.', null, 'high'),
  ('man-bac', 41, 'Man Bac', 'Ninh Bình, Vietnam', 20.2, 105.9, 4000, 3500, 'Neolithic cemetery where ancient genomes show farmers with southern Chinese ancestry mixed with local hunter-gatherers.', null, 'high'),
  ('teouma', 42, 'Teouma', 'Efate, Vanuatu', -17.75, 168.4, 3000, 2560, 'Lapita cemetery; the first settlers of Remote Oceania had almost no Papuan ancestry.', null, 'high'),
  ('qeqertasussuk', 43, 'Qeqertasussuk', 'Disko Bay, Greenland', 68.8, -51.5, 4400, 3900, 'Saqqaq (Paleo-Inuit) site; a ~4,000-year-old hair tuft gave the first ancient human genome.', null, 'high'),
  ('lanse-aux-meadows', 44, 'L''Anse aux Meadows', 'Newfoundland, Canada', 51.6, -55.53, 979, 979, 'Norse site where wood cut with metal tools is dated to exactly AD 1021 by the cosmic-ray event of AD 993.', null, 'high'),
  ('ubeidiya', 45, '''Ubeidiya', 'Jordan Valley, Israel', 32.69, 35.56, 1900000, 1200000, 'Acheulean site. Long dated to ~1.6–1.2 million years ago; a 2026 burial-dating study suggests ~1.9 million years, which is contested.', null, 'medium'),
  ('shangchen', 46, 'Shangchen', 'Loess Plateau, China', 34.2, 109.5, 2100000, 1260000, 'Stone tools in loess layers from ~2.1 million years ago, the oldest hominin evidence outside Africa. The makers are unidentified.', null, 'high'),
  ('gongwangling', 47, 'Gongwangling (Lantian)', 'Shaanxi, China', 34.2, 109.5, 1650000, 1540000, 'Homo erectus cranium dated to ~1.63 million years ago.', null, 'high'),
  ('zhoukoudian', 48, 'Zhoukoudian', 'Beijing, China', 39.69, 115.93, 850000, 400000, 'The ''Peking Man'' cave; the lower layers are dated by burial dating to ~770,000 years ago.', null, 'high'),
  ('yuanmou', 49, 'Yuanmou', 'Yunnan, China', 25.7, 101.87, 1750000, 1650000, 'Two hominin incisors dated to ~1.7 million years ago.', null, 'medium'),
  ('attirampakkam', 50, 'Attirampakkam', 'Tamil Nadu, India', 13.23, 79.89, 1580000, 1070000, 'Acheulean tools dated to ~1.5 million years ago; no fossils.', null, 'medium'),
  ('sangiran', 51, 'Sangiran', 'Central Java, Indonesia', -7.45, 110.83, 1500000, 800000, 'Rich Homo erectus fossil area; first appearance ~1.3 million years ago.', null, 'high'),
  ('ngandong', 52, 'Ngandong', 'Solo River, Java', -7.18, 111.36, 117000, 108000, 'The last known Homo erectus, 117,000–108,000 years ago.', null, 'high'),
  ('korolevo', 53, 'Korolevo', 'Transcarpathia, Ukraine', 48.15, 23.13, 1520000, 1320000, 'Stone tools dated by burial dating to ~1.42 million years ago, the oldest dated evidence of hominins in Europe.', null, 'medium'),
  ('pirro-nord', 54, 'Pirro Nord', 'Apulia, Italy', 41.8, 15.4, 1700000, 1300000, 'Stone tools with a fauna dated by biochronology to ~1.7–1.3 million years ago.', null, 'medium'),
  ('barranco-leon', 55, 'Barranco León (Orce)', 'Granada, Spain', 37.72, -2.48, 1500000, 1300000, 'A ~1.4-million-year-old hominin tooth with stone tools.', null, 'medium'),
  ('sima-del-elefante', 56, 'Sima del Elefante (Atapuerca)', 'Burgos, Spain', 42.35, -3.52, 1400000, 1100000, 'A partial face (ATE7-1, ''Pink''), tentatively Homo aff. erectus, 1.4–1.1 million years old.', null, 'medium'),
  ('happisburgh', 57, 'Happisburgh', 'Norfolk, England', 52.83, 1.53, 950000, 780000, 'Tools and footprints over 780,000 years old, the earliest people in northern Europe; makers unidentified.', null, 'medium'),
  ('wolo-sege', 58, 'Wolo Sege & Mata Menge', 'So''a Basin, Flores', -8.67, 121.1, 1020000, 700000, 'Stone tools from ~1.02 million years ago (Wolo Sege) and small H. floresiensis-like fossils from ~700,000 (Mata Menge).', null, 'high'),
  ('calio', 59, 'Calio & Talepu', 'Walanae Basin, Sulawesi', -4.2, 120, 1480000, 118000, 'Stone tools at least 1.04 million years old (Calio) and 194,000–118,000 years old (Talepu). No hominin fossils: the makers are unknown.', null, 'medium'),
  ('kalinga', 60, 'Kalinga site', 'Cagayan Valley, Luzon', 17.5, 121.4, 777000, 631000, 'A butchered rhinoceros with stone tools ~709,000 years old. No hominin fossils.', null, 'medium'),
  ('callao-cave', 61, 'Callao Cave', 'Cagayan, Luzon', 17.7, 121.82, 67000, 50000, 'Fossils of Homo luzonensis with minimum ages of ~67,000 and ~50,000 years.', null, 'high'),
  ('tabun', 62, 'Tabun Cave', 'Mount Carmel, Israel', 32.67, 34.97, 143000, 112000, 'Neanderthal burial (Tabun C1); age estimates span ~143,000–112,000 years.', null, 'medium'),
  ('amud', 63, 'Amud Cave', 'Galilee, Israel', 32.87, 35.5, 70000, 50000, 'Neanderthal remains including an infant burial, ~70,000–50,000 years old.', null, 'medium'),
  ('shanidar', 64, 'Shanidar Cave', 'Iraqi Kurdistan', 36.83, 44.22, 75000, 60000, 'Multiple Neanderthal individuals, including the ''flower burial'' context.', null, 'high'),
  ('teshik-tash', 65, 'Teshik-Tash', 'Uzbekistan', 38.2, 67, 70000, 40000, 'Neanderthal child; its mtDNA links it to European Neanderthals.', null, 'medium'),
  ('okladnikov', 66, 'Okladnikov Cave', 'Altai, Russia', 51.8, 84.5, 50000, 40000, 'Neanderthal remains with mtDNA close to European Neanderthals.', null, 'medium'),
  ('chagyrskaya', 67, 'Chagyrskaya Cave', 'Altai, Russia', 51.44, 83.15, 59000, 49000, 'Neanderthals with Micoquian tools linked to Central and Eastern Europe; a high-coverage genome (Chagyrskaya 8).', null, 'high'),
  ('mezmaiskaya', 68, 'Mezmaiskaya Cave', 'North Caucasus, Russia', 44.17, 40, 100000, 40000, 'Neanderthal remains whose genomes record a late population turnover.', null, 'medium'),
  ('vindija', 69, 'Vindija Cave', 'Croatia', 46.3, 16.08, 55000, 40000, 'Late Neanderthals; the Vindija genome is close to the Chagyrskaya Neanderthals of Siberia.', null, 'high'),
  ('harbin', 70, 'Harbin', 'Heilongjiang, China', 45.75, 126.65, 309000, 146000, 'A nearly complete cranium (''Dragon Man'') at least ~146,000 years old, identified as Denisovan by proteins and mtDNA in 2025.', null, 'high'),
  ('tam-ngu-hao', 71, 'Tam Ngu Hao 2 (Cobra Cave)', 'Annamite Chain, Laos', 20.2, 103.4, 164000, 131000, 'A Denisovan child''s molar, 164,000–131,000 years old.', null, 'medium'),
  ('penghu', 72, 'Penghu Channel', 'Taiwan Strait', 23.5, 119.8, 190000, 10000, 'A mandible dredged from the sea floor, identified as a male Denisovan by proteins (2025). Its age is uncertain (~190,000–130,000 or ~70,000–10,000 years).', null, 'medium');
