insert into public.historical_periods (id, sort_order, name, short_name, start_bp, end_bp, description, confidence) values
  ('early-hominins', 0, 'Early hominins', 'Early hominins', 3500000, 2580000, 'Late Pliocene. Australopithecus afarensis lives in East Africa. The oldest known stone tools (Lomekwi 3, ~3.3 million years ago) are older than the earliest known fossils of the genus Homo, so who made them is unknown.', 'medium'),
  ('early-pleistocene', 1, 'Early Pleistocene', 'Early Pleistocene', 2580000, 774000, 'The Pleistocene begins ~2.58 million years ago. Early Homo appears in Africa and coexists with Paranthropus. By ~1.8 million years ago Homo is at Dmanisi in Georgia, the oldest hominin fossils known outside Africa, and later in China and Java.', 'high'),
  ('middle-pleistocene', 2, 'Middle Pleistocene', 'Middle Pleistocene', 774000, 300000, 'Geologically ~774,000–129,000 years ago. Lineages diverge: the Neanderthal lineage appears in Europe, Homo erectus persists in Asia, and small-bodied hominins live on Flores. Evolution here is branching, not a ladder.', 'medium'),
  ('emergence', 3, 'Emergence in Africa', 'Emergence', 300000, 200000, 'The oldest fossils attributed to Homo sapiens, from Jebel Irhoud in Morocco, date to roughly 300,000 years ago. Early sapiens remains are spread across Africa.', 'high'),
  ('early-dispersals', 4, 'Early dispersals', 'Early dispersals', 200000, 75000, 'Fossils in the Levant show that Homo sapiens left Africa at least intermittently long before the main dispersal. How lasting these early groups were is debated.', 'medium'),
  ('main-dispersal', 5, 'Main out-of-Africa dispersal', 'Out of Africa', 75000, 40000, 'Genetic evidence indicates that most present-day non-African populations descend from a dispersal roughly 50,000–70,000 years ago.', 'high'),
  ('late-pleistocene', 6, 'Late Pleistocene', 'Late Pleistocene', 40000, 11700, 'Homo sapiens is present across Africa, Eurasia and Sahul. The Last Glacial Maximum peaks around 26,000–19,000 years ago.', 'high'),
  ('holocene', 7, 'Holocene', 'Holocene', 11700, 0, 'The current geological epoch, beginning at the end of the last glacial period. Farming emerges independently in several regions.', 'high');
insert into public.migration_routes (id, sort_order, species_id, name, category, path, branches, particle_config, confidence, data_status, uncertainty, origin, destination, intermediate_regions, path_description, description, people, historical_context, significance, camera) values
  ('africa-levant', 0, 'homo-sapiens', 'Africa → Levant', 'Early dispersal', '[{"name":"East Africa","lat":6.5,"lng":37,"year":135000},{"name":"Middle Nile","lat":15.6,"lng":32.6,"year":128000},{"name":"Nubian Nile","lat":20.5,"lng":30.9,"year":122000},{"name":"Upper Egypt","lat":25.7,"lng":32.6,"year":116000},{"name":"Lower Nile","lat":29.6,"lng":31.3,"year":111000},{"name":"Sinai","lat":30.4,"lng":33.7,"year":107000},{"name":"Southern Levant","lat":32.4,"lng":35.6,"year":100000}]'::jsonb, null, '{"count":4200,"clusterCount":6,"spreadKm":165,"edgeShare":0.3,"groupLengthKm":[110,240],"originSpreadKm":260,"speedVariation":0.08,"stagger":0.35,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":240,"east":75}}'::jsonb, 'medium', 'illustrative', 'Homo sapiens was in the Levant by ~120,000–90,000 years ago, but the path out of Africa and the timing drawn here are illustrative. Whether these groups left lasting descendants is debated.', 'East Africa', 'Southern Levant', array['Nile Valley', 'Sinai']::text[], 'Drawn northward along the Nile corridor and across Sinai. A southern crossing at Bab-el-Mandeb is also discussed in the literature.', 'Fossils show Homo sapiens in the southern Levant long before the main out-of-Africa dispersal.', 'Early Homo sapiens hunter-gatherers from northeast Africa. Nothing is known about their language or social identity.', 'The Last Interglacial (~130,000–115,000 years ago) brought wetter phases that periodically made the Sahara and Sinai more passable.', 'Shows that leaving Africa was not a single event; our species ranged into Southwest Asia repeatedly, sometimes sharing the region with Neanderthals.', '{"lat":17,"lng":33,"distance":2.3}'::jsonb),
  ('out-of-africa-south', 1, 'homo-sapiens', 'Africa → South Asia', 'Main out-of-Africa dispersal', '[{"name":"Horn of Africa","lat":9.5,"lng":41,"year":70000},{"name":"Bab-el-Mandeb","lat":12.7,"lng":43.3,"year":67000},{"name":"Southern Arabia","lat":14.3,"lng":48.5,"year":64000},{"name":"Dhofar","lat":17,"lng":54,"year":61500},{"name":"Oman","lat":22.5,"lng":58.8,"year":59500},{"name":"Strait of Hormuz","lat":26.2,"lng":56.4,"year":58000},{"name":"Makran coast","lat":25.3,"lng":61.5,"year":56500},{"name":"Indus delta","lat":24.8,"lng":67.5,"year":55000},{"name":"Indian subcontinent","lat":21,"lng":77.5,"year":52000}]'::jsonb, null, '{"count":4950,"clusterCount":6,"spreadKm":160,"edgeShare":0.3,"groupLengthKm":[120,280],"originSpreadKm":220,"speedVariation":0.08,"stagger":0.3,"splitGroups":2,"splitAt":0.55,"dispersalKm":{"north":320,"east":280}}'::jsonb, 'medium', 'illustrative', 'Genetics strongly supports a major dispersal ~70,000–50,000 years ago, but its exact timing and whether it left via Bab-el-Mandeb or Sinai are debated. This coastal path is illustrative.', 'Horn of Africa', 'Indian subcontinent', array['Bab-el-Mandeb', 'Southern Arabia', 'Persian Gulf coast', 'Makran']::text[], 'Drawn across the Bab-el-Mandeb strait and along the Arabian and Iranian coasts, following the ''southern route'' hypothesis.', 'The dispersal from which most present-day non-African populations descend.', 'Homo sapiens hunter-gatherers from northeast Africa, probably in small, mobile groups. Their specific identity is unknown.', 'A glacial world with sea levels well below today''s, narrowing the Bab-el-Mandeb strait and exposing coastal shelves now under water.', 'Ancestors of most people outside Africa took part in this dispersal, and shortly after it they interbred with Neanderthals.', '{"lat":19,"lng":55,"distance":2.7}'::jsonb),
  ('levant-europe', 2, 'homo-sapiens', 'Southwest Asia → Europe', 'Into Europe', '[{"name":"Northern Levant","lat":34.5,"lng":36.5,"year":55000},{"name":"Anatolia","lat":38.5,"lng":33.5,"year":52000},{"name":"Thrace","lat":41.3,"lng":28.5,"year":49000},{"name":"Lower Danube","lat":43.3,"lng":25,"year":46000},{"name":"Carpathian Basin","lat":46.5,"lng":19.5,"year":44000},{"name":"Upper Danube","lat":48.3,"lng":13.5,"year":42500},{"name":"Western Europe","lat":46.8,"lng":4.5,"year":40000}]'::jsonb, null, '{"count":4300,"clusterCount":6,"spreadKm":150,"edgeShare":0.32,"groupLengthKm":[110,260],"originSpreadKm":180,"speedVariation":0.08,"stagger":0.3,"splitGroups":2,"splitAt":0.6,"dispersalKm":{"north":280,"east":420}}'::jsonb, 'high', 'illustrative', 'Homo sapiens is well attested in Europe by ~45,000 years ago. The Danube corridor drawn here is one plausible path; earlier incursions such as Grotte Mandrin (~54,000 years ago) are debated and not shown as a separate wave.', 'Southwest Asia', 'Western Europe', array['Anatolia', 'Balkans', 'Danube corridor', 'Central Europe']::text[], 'Drawn across Anatolia and Thrace, then westward along the Danube corridor into central and western Europe.', 'Homo sapiens spreads into a continent already occupied by Neanderthals.', 'Homo sapiens hunter-gatherers carrying early Upper Palaeolithic technologies. Several early groups left little ancestry in later Europeans.', 'A cold, climatically unstable phase of the last glacial period; Neanderthals disappear from the record over the following millennia.', 'Marks the overlap and eventual replacement of Neanderthals in Europe, and the start of Europe''s Upper Palaeolithic.', '{"lat":43,"lng":22,"distance":2.5}'::jsonb),
  ('levant-caucasus', 3, 'homo-sapiens', 'Southwest Asia → Caucasus', 'Into the Caucasus', '[{"name":"Northern Levant","lat":36.2,"lng":37.2,"year":45000},{"name":"Upper Tigris","lat":37.6,"lng":41,"year":43000},{"name":"Lake Van basin","lat":38.7,"lng":43,"year":41000},{"name":"Armenian Highlands","lat":40.2,"lng":44.4,"year":39000},{"name":"Southern Caucasus","lat":42.2,"lng":43.1,"year":36000}]'::jsonb, null, '{"count":2300,"clusterCount":5,"spreadKm":85,"edgeShare":0.3,"groupLengthKm":[70,150],"originSpreadKm":130,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":110,"east":190}}'::jsonb, 'medium', 'illustrative', 'Upper Palaeolithic occupation of the southern Caucasus is dated to roughly 42,000–38,000 years ago; where these groups came from and the path drawn here are illustrative.', 'Northern Levant / Upper Mesopotamia', 'Southern Caucasus', array['Upper Tigris', 'Eastern Anatolia', 'Armenian Highlands']::text[], 'Drawn north through the uplands of eastern Anatolia and the Armenian Highlands into the valleys of the southern Caucasus.', 'Homo sapiens reaches the mountain valleys of the southern Caucasus, another former Neanderthal region.', 'Upper Palaeolithic Homo sapiens hunter-gatherers. No specific identity can be assigned.', 'Neanderthal occupation of the region ends around the same time Upper Palaeolithic sites appear.', 'The Caucasus links Southwest Asia with the steppe; later genomes from here help explain West Eurasian ancestry.', '{"lat":39.5,"lng":41.5,"distance":1.95}'::jsonb),
  ('sunda-sahul', 4, 'homo-sapiens', 'Southeast Asia → Sahul', 'Across Wallacea', '[{"name":"Mainland Southeast Asia","lat":18.5,"lng":102.5,"year":60000},{"name":"Malay Peninsula","lat":6,"lng":101.5,"year":57000},{"name":"Sunda Shelf","lat":0,"lng":106.5,"year":54500},{"name":"Java","lat":-7.3,"lng":111,"year":52000},{"name":"Lesser Sunda Islands","lat":-8.6,"lng":120.5,"year":49500},{"name":"Timor","lat":-9.5,"lng":124.8,"year":48000},{"name":"Sahul Shelf","lat":-11.5,"lng":129.5,"year":46500},{"name":"Northern Australia","lat":-13.5,"lng":133.5,"year":45000}]'::jsonb, '[{"id":"northern-route","name":"Northern route (via Sulawesi)","fromWaypoint":3,"path":[{"name":"Borneo coast","lat":-3,"lng":116,"year":50500},{"name":"Sulawesi","lat":-2,"lng":120.6,"year":49000},{"name":"Maluku","lat":-3.3,"lng":128.5,"year":47500},{"name":"New Guinea","lat":-5.5,"lng":140.5,"year":45000}],"share":0.35,"note":"Northern (Sulawesi–Maluku) and southern (Timor) crossings into Sahul are both proposed; neither is established."}]'::jsonb, '{"count":4400,"clusterCount":6,"spreadKm":130,"edgeShare":0.3,"groupLengthKm":[120,280],"originSpreadKm":200,"speedVariation":0.08,"stagger":0.3,"splitGroups":2,"splitAt":0.55,"dispersalKm":{"north":380,"east":420}}'::jsonb, 'medium', 'illustrative', 'Arrival in Sahul is dated anywhere from ~65,000 to ~50,000 years ago depending on the site and method; this is actively debated. The island-hopping path is one of several proposed.', 'Mainland Southeast Asia', 'Northern Sahul (Australia)', array['Sunda Shelf (now submerged)', 'Java', 'Wallacea', 'Timor']::text[], 'Drawn down the exposed Sunda Shelf and through the Lesser Sunda Islands, where open-sea crossings were unavoidable, to the Sahul Shelf.', 'The first people to reach Australia and New Guinea, which required repeated sea crossings.', 'Homo sapiens hunter-gatherers moving through island Southeast Asia, ancestral to Aboriginal Australians and Papuans.', 'Low glacial sea levels joined western Indonesia into the continent of Sunda and Australia–New Guinea into Sahul; the Wallacean islands between them were never connected by land.', 'Among the earliest evidence of deliberate open-water voyaging by humans.', '{"lat":-5,"lng":117,"distance":2.7}'::jsonb),
  ('beringia-americas', 5, 'homo-sapiens', 'Asia → Beringia → Americas', 'Peopling of the Americas', '[{"name":"Northeast Siberia","lat":70.7,"lng":135.4,"year":32000},{"name":"Western Beringia","lat":66.5,"lng":172,"year":27000},{"name":"Bering Land Bridge","lat":65.6,"lng":-170,"year":24000},{"name":"Eastern Beringia","lat":64.5,"lng":-157,"year":18000},{"name":"Gulf of Alaska","lat":59,"lng":-141,"year":16500},{"name":"Pacific Northwest","lat":49.5,"lng":-126,"year":16000},{"name":"California coast","lat":36,"lng":-121.5,"year":15700},{"name":"Central America","lat":14,"lng":-90.5,"year":15300},{"name":"Northern Andes","lat":4,"lng":-77,"year":15000},{"name":"Southern South America","lat":-41.5,"lng":-72.8,"year":14500}]'::jsonb, '[{"id":"interior","name":"Interior route (debated)","fromWaypoint":3,"path":[{"name":"Yukon","lat":63,"lng":-136,"year":16800},{"name":"Mackenzie corridor","lat":57.5,"lng":-118,"year":15800},{"name":"Northern Plains","lat":50.5,"lng":-110,"year":15200},{"name":"Interior North America","lat":40,"lng":-97,"year":14500}],"share":0.3,"note":"An inland route east of the Rocky Mountains depended on when an ice-free corridor opened; its timing relative to the first arrivals is debated."}]'::jsonb, '{"count":5700,"clusterCount":6,"spreadKm":150,"edgeShare":0.3,"groupLengthKm":[160,380],"originSpreadKm":260,"speedVariation":0.08,"stagger":0.25,"splitGroups":2,"splitAt":0.6,"dispersalKm":{"north":650,"east":420}}'::jsonb, 'medium', 'illustrative', 'People were in South America by ~14,500 years ago. Earlier arrivals (e.g. White Sands footprints, ~23,000–21,000 years ago) and the coastal vs. ice-free-corridor route are debated. Pacing here is illustrative.', 'Northeast Siberia', 'South America', array['Beringia', 'Alaska', 'Pacific coast', 'Central America', 'Andes']::text[], 'Drawn across the exposed Bering land bridge, slowing in Beringia (the ''standstill''), then down the Pacific coast to South America.', 'The last continental landmasses settled by Homo sapiens before the Holocene.', 'Homo sapiens from northeast Asia; the ancestors of Indigenous peoples of the Americas.', 'The Last Glacial Maximum: ice sheets covered much of North America, and low sea level exposed a broad land bridge between Asia and Alaska.', 'Completes the dispersal of Homo sapiens across every continent except Antarctica.', '{"lat":48,"lng":-150,"distance":3.3}'::jsonb),
  ('arabia-interior-early', 6, 'homo-sapiens', 'Into Arabia (early)', 'Early dispersal', '[{"name":"Bab-el-Mandeb","lat":12.6,"lng":43.4,"year":130000},{"name":"Southern Arabia","lat":17,"lng":48,"year":128000},{"name":"Jebel Faya","lat":25.12,"lng":55.85,"year":125000},{"name":"Rub'' al Khali margin","lat":23.5,"lng":50,"year":105000},{"name":"Nefud (Al Wusta)","lat":28.4,"lng":40.3,"year":88000}]'::jsonb, null, '{"count":1300,"clusterCount":5,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Jebel Faya has stone tools only, so its makers are inferred. Al Wusta rests on one finger bone. These populations probably did not leave descendants among later Eurasians. The path between the sites is illustrative.', 'Horn of Africa', 'Northern Arabia (Nefud)', array['Southern Arabia', 'Jebel Faya', 'Rub'' al Khali margin']::text[], 'Drawn from the Bab-el-Mandeb across southern Arabia to Jebel Faya, then inland to the lakes of the Nefud.', 'Humid phases turned Arabia green and let early Homo sapiens move into its interior well before the main out-of-Africa dispersal.', 'Homo sapiens hunter-gatherers using Middle Stone Age–like tool kits; their specific identity is unknown.', 'Interglacial and later humid phases created lakes and grasslands across what is now desert.', 'Shows that Homo sapiens left Africa more than once, and that early dispersals could fail or be absorbed.', '{"lat":22,"lng":47,"distance":2.3}'::jsonb),
  ('apidima-early-europe', 7, 'homo-sapiens', 'Apidima: an early foray into Europe', 'Early dispersal (contested)', '[{"name":"Southern Levant","lat":32.7,"lng":35,"year":225000},{"name":"Southwest Anatolia","lat":37,"lng":28,"year":218000},{"name":"Aegean coast","lat":37.5,"lng":24,"year":214000},{"name":"Apidima, Mani","lat":36.63,"lng":22.38,"year":210000}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'low', 'illustrative', 'Apidima 1 is a distorted partial skull and its attribution to Homo sapiens is disputed; its age (>210,000 years) is a minimum. The route is entirely illustrative.', 'Levant', 'Southern Greece', array['Anatolia', 'Aegean']::text[], 'An illustrative path from the Levant along the Anatolian coast to the Peloponnese.', 'If Apidima 1 is Homo sapiens, our species reached southeastern Europe more than 200,000 years ago and was later replaced by Neanderthals.', 'An early Homo sapiens population, if the attribution holds; nothing else is known about them.', 'A Middle Pleistocene Europe occupied by Neanderthals and their ancestors.', 'A possible very early, unsuccessful dispersal of Homo sapiens.', '{"lat":36,"lng":27,"distance":2}'::jsonb),
  ('early-mainland-sea', 8, 'homo-sapiens', 'Early Southeast Asia & Sumatra', 'Early dispersal', '[{"name":"Northeast India","lat":25.5,"lng":91,"year":90000},{"name":"Northern Myanmar","lat":22,"lng":96,"year":88000},{"name":"Tam Pà Ling, Laos","lat":20.21,"lng":103.41,"year":86000},{"name":"Malay Peninsula","lat":4.5,"lng":101.5,"year":75000},{"name":"Lida Ajer, Sumatra","lat":-0.3,"lng":100.4,"year":68000}]'::jsonb, null, '{"count":1100,"clusterCount":5,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Both Tam Pà Ling (86,000–68,000) and Lida Ajer (73,000–63,000) are older than the main genetic out-of-Africa signal, so these people may have no living descendants. Claims of 80,000–120,000-year-old teeth at Fuyan Cave (China) were later re-dated to the Holocene and are not drawn.', 'South Asia', 'Sumatra', array['Myanmar', 'Northern Laos', 'Malay Peninsula']::text[], 'Illustrative inland path from northeast India through northern Laos and down the Malay Peninsula to Sumatra.', 'Fossils show Homo sapiens in Southeast Asia''s rainforests earlier than the main dispersal.', 'Homo sapiens hunter-gatherers adapted to forests; specific identity unknown.', 'A cooler world with lower seas, joining Sumatra to the mainland as part of Sundaland.', 'Shows early modern humans could live in tropical rainforest, long thought a barrier.', '{"lat":14,"lng":100,"distance":2.4}'::jsonb),
  ('north-eurasia-siberia', 9, 'homo-sapiens', 'Across northern Eurasia to the Arctic', 'Upper Palaeolithic dispersal', '[{"name":"Zagros","lat":34,"lng":47,"year":50000},{"name":"Central Asia","lat":41,"lng":64,"year":47000},{"name":"Ust''-Ishim","lat":57.7,"lng":71.2,"year":45000},{"name":"Altai","lat":51.4,"lng":84.7,"year":43000},{"name":"Lake Baikal","lat":52.5,"lng":104,"year":35000},{"name":"Yana River","lat":70.7,"lng":135.4,"year":31600}]'::jsonb, null, '{"count":1600,"clusterCount":7,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'The sites and ages are secure; the path between them is interpolated. Ust''-Ishim has no living descendants, and the Yana people (Ancient North Siberians) were later largely replaced.', 'Iranian Plateau', 'Arctic Siberia', array['Central Asia', 'Western Siberia', 'Altai', 'Lake Baikal']::text[], 'Drawn from the Zagros through Central Asia to the Irtysh, then east along the southern Siberian belt and north to the Yana River.', 'Modern humans reached the steppes and taiga of Siberia by ~45,000 years ago and the Arctic Circle by ~32,000.', 'Upper Palaeolithic hunters; genomes show several lineages, some with no living descendants.', 'Cold, dry glacial steppe with mammoth, bison and horse.', 'Extreme cold adaptation; the Ancient North Siberians contributed ancestry to later Siberians and Native Americans.', '{"lat":55,"lng":95,"distance":3}'::jsonb),
  ('east-asia-japan', 10, 'homo-sapiens', 'East Asia to Japan', 'Upper Palaeolithic dispersal', '[{"name":"Southern China","lat":25,"lng":110,"year":48000},{"name":"North China Plain","lat":35,"lng":114,"year":43000},{"name":"Tianyuan Cave","lat":39.65,"lng":115.87,"year":40000},{"name":"Korean Peninsula","lat":36.5,"lng":127.5,"year":39000},{"name":"Kyushu","lat":33,"lng":131,"year":38000},{"name":"Honshu","lat":36,"lng":138,"year":37000}]'::jsonb, null, '{"count":1300,"clusterCount":5,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Tianyuan is securely dated. The Korea waypoint is geographic interpolation, and the ~38,000-year arrival in Japan rests on the archaeological record rather than fossils.', 'Southern China', 'Japanese archipelago', array['North China', 'Korean Peninsula', 'Tsushima Strait']::text[], 'Drawn north through China to Tianyuan, then via the Korean Peninsula and Tsushima Strait to Kyushu and Honshu.', 'Modern humans spread through East Asia and crossed the sea to Japan by ~38,000 years ago.', 'Upper Palaeolithic hunter-gatherers; genomes link Tianyuan to present-day East Asians.', 'Glacial seas were lower but Japan was never joined to Korea: reaching it needed a sea crossing.', 'Ancestors of the Jōmon, who form one of three ancestral layers of present-day Japanese.', '{"lat":36,"lng":124,"distance":2.4}'::jsonb),
  ('ryukyu-seafaring', 11, 'homo-sapiens', 'Taiwan to the Ryukyus by sea', 'Upper Palaeolithic seafaring', '[{"name":"South China coast","lat":24.5,"lng":118.5,"year":38000},{"name":"Northern Taiwan","lat":25.1,"lng":121.8,"year":36000},{"name":"Yonaguni","lat":24.45,"lng":123,"year":35000},{"name":"Ishigaki & Miyako","lat":24.5,"lng":125,"year":33500},{"name":"Okinawa","lat":26.5,"lng":128,"year":32000}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'The Ryukyu sites date to ~35,000–30,000 years ago; the exact crossing points are unknown. A 2019 dugout-canoe voyage showed the Kuroshio crossing was feasible, not that it happened that way.', 'South China coast', 'Okinawa', array['Taiwan', 'Yonaguni', 'Ishigaki']::text[], 'Island-hopping from Taiwan across the Kuroshio current to the southern Ryukyus and Okinawa.', 'Palaeolithic seafarers crossed one of the world''s strongest ocean currents to reach the Ryukyu Islands.', 'Upper Palaeolithic islanders; their identity is unknown.', 'Even with lower sea levels, Yonaguni lay over 100 km from Taiwan across the Kuroshio.', 'Some of the earliest deliberate open-sea voyages known.', '{"lat":25,"lng":124,"distance":1.9}'::jsonb),
  ('tibetan-plateau', 12, 'homo-sapiens', 'Onto the Tibetan Plateau', 'Upper Palaeolithic dispersal', '[{"name":"Upper Yellow River","lat":36,"lng":103,"year":45000},{"name":"Qinghai Lake","lat":36.9,"lng":100.2,"year":43500},{"name":"Qaidam margin","lat":36.5,"lng":96,"year":42000},{"name":"Nwya Devu","lat":31.6,"lng":90,"year":40000}]'::jsonb, null, '{"count":600,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Nwya Devu has stone tools but no fossils. Whether its makers were Homo sapiens or Denisovans is not settled; the route assumes Homo sapiens.', 'Upper Yellow River', 'Central Tibetan Plateau', array['Qinghai Lake', 'Qaidam Basin']::text[], 'Illustrative ascent from the northeastern plateau margin to the high interior.', 'Stone tools show people at 4,600 m on the Tibetan Plateau 40,000–30,000 years ago.', 'Unknown toolmakers, probably Homo sapiens; Denisovans had been on the plateau earlier.', 'Very high, cold and low in oxygen; Denisovans had lived at Baishiya Karst Cave on the plateau''s edge.', 'The oldest evidence of humans living at very high altitude.', '{"lat":34,"lng":96,"distance":2}'::jsonb),
  ('north-africa-backflow', 13, 'homo-sapiens', 'Back to North Africa', 'Late Pleistocene back-migration', '[{"name":"Southern Levant","lat":32,"lng":35,"year":25000},{"name":"Sinai","lat":30,"lng":33.5,"year":22500},{"name":"Nile Delta","lat":30.8,"lng":31,"year":21500},{"name":"Cyrenaica","lat":32.5,"lng":22,"year":20000},{"name":"Tunisia","lat":35,"lng":9,"year":18000},{"name":"Taforalt","lat":34.81,"lng":-2.41,"year":15000}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Genomes show Near Eastern ancestry at Taforalt by ~15,000 years ago, but the timing and route of the movement are inferred, not documented.', 'Levant', 'Morocco', array['Sinai', 'Cyrenaica', 'Tunisia']::text[], 'Drawn along the Mediterranean coast of North Africa.', 'Ancient DNA shows that people with Near Eastern ancestry moved back into North Africa before ~15,000 years ago.', 'Ancestors of the Iberomaurusian makers of Taforalt; about two-thirds of their ancestry is Natufian-related.', 'Around and after the Last Glacial Maximum.', 'Movement out of Africa was not one-way: Eurasian ancestry returned to Africa long before farming.', '{"lat":31,"lng":15,"distance":2.4}'::jsonb),
  ('eurasian-backflow-east-africa', 14, 'homo-sapiens', 'West Eurasian back-flow to East Africa', 'Holocene back-migration', '[{"name":"Levant","lat":33,"lng":36,"year":5000},{"name":"Sinai","lat":29.5,"lng":33.5,"year":4700},{"name":"Nile valley","lat":25,"lng":32.8,"year":4300},{"name":"Ethiopian Highlands","lat":9,"lng":38.7,"year":3500},{"name":"Kenyan Rift","lat":0.5,"lng":36,"year":3000}]'::jsonb, null, '{"count":800,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Admixture dates cluster around ~3,000 years ago. The first estimates of Eurasian ancestry across all of Africa were corrected; the East African signal stands. The route is illustrative.', 'Levant', 'East Africa', array['Sinai', 'Nile valley', 'Ethiopian Highlands']::text[], 'Illustrative path up the Nile into the Ethiopian Highlands and Rift.', 'West Eurasian ancestry, with Near Eastern farmer components, entered East Africa in the last few thousand years.', 'Groups carrying Levantine-farmer-related ancestry; their identity is unknown.', 'The mid-to-late Holocene, as pastoralism spread across northeast Africa.', 'Explains West Eurasian ancestry in many present-day East Africans.', '{"lat":15,"lng":36,"distance":2.5}'::jsonb),
  ('pastoralist-spread', 15, 'homo-sapiens', 'Herders into East & Southern Africa', 'Holocene expansion', '[{"name":"Sudanese Nile","lat":15.6,"lng":32.5,"year":6000},{"name":"Lake Turkana","lat":3.5,"lng":36,"year":5000},{"name":"Central Rift, Kenya","lat":-0.5,"lng":36.1,"year":3500},{"name":"Northern Tanzania","lat":-3.4,"lng":35.5,"year":3000},{"name":"Zambia–Botswana","lat":-18,"lng":24,"year":2000},{"name":"Western Cape","lat":-33,"lng":18.5,"year":1300}]'::jsonb, null, '{"count":1100,"clusterCount":5,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Ancient DNA documents the East African steps well. The arrival in southern Africa (~2,000–1,300 years ago) is inferred from East African ancestry in present-day Khoe groups.', 'Sudanese Nile', 'Southern Africa', array['Lake Turkana', 'Kenyan Rift', 'Tanzania', 'Zambia–Botswana']::text[], 'Drawn south through the Rift Valley, then across the interior to the Western Cape.', 'Cattle, sheep and goat herding spread from northeast Africa south in several steps, with people mixing with local foragers.', 'Northeast African herders who mixed with local hunter-gatherers; later, ancestors of Khoe pastoralists.', 'The end of the African Humid Period and drying of the Sahara.', 'Brought herding to East and Southern Africa before farming did.', '{"lat":-5,"lng":32,"distance":3}'::jsonb),
  ('bantu-expansion', 16, 'homo-sapiens', 'Bantu expansion', 'Holocene farmer expansion', '[{"name":"Grassfields, Cameroon–Nigeria","lat":6,"lng":10.5,"year":5000},{"name":"Southern Cameroon","lat":3,"lng":12,"year":4000},{"name":"Congo Basin","lat":-1,"lng":20,"year":3200},{"name":"Great Lakes","lat":-1.5,"lng":30.5,"year":2500},{"name":"Zambia","lat":-13,"lng":28,"year":1800},{"name":"Limpopo","lat":-22,"lng":32,"year":1700},{"name":"KwaZulu-Natal","lat":-29,"lng":30.5,"year":1500}]'::jsonb, '[{"id":"western","name":"Western branch (Angola)","fromWaypoint":1,"share":0.35,"path":[{"name":"Lower Congo","lat":-6,"lng":14,"year":2500},{"name":"Angola","lat":-12.5,"lng":15.5,"year":2000},{"name":"Northern Namibia","lat":-18,"lng":16,"year":1500}],"note":"A western stream through the rainforest to the Atlantic coast and Angola; genetics favours a late split around the Zambia–DRC region."}]'::jsonb, '{"count":1800,"clusterCount":7,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'The expansion is well established, but its branching is debated. Pottery dates show a rainforest population collapse around 400–600 CE, so settlement was not continuous.', 'Cameroon–Nigeria borderlands', 'Eastern and Southern Africa', array['Congo Basin', 'Great Lakes', 'Zambia', 'Limpopo']::text[], 'An eastern stream through the Great Lakes and a western stream to Angola.', 'Farmers speaking Bantu languages spread from West-Central Africa across much of sub-Saharan Africa.', 'Ancestors of present-day Bantu-speaking peoples, who mixed with local foragers and herders.', 'Farming, pottery and later iron working; changing rainforest cover.', 'Shaped the languages, genetics and farming of most of sub-Saharan Africa.', '{"lat":-10,"lng":24,"distance":3}'::jsonb),
  ('neolithic-danubian', 17, 'homo-sapiens', 'First farmers: Danubian route', 'Neolithic expansion', '[{"name":"Çatalhöyük","lat":37.67,"lng":32.83,"year":9500},{"name":"Marmara","lat":40.2,"lng":29,"year":8500},{"name":"Thrace","lat":42,"lng":25,"year":8200},{"name":"Iron Gates","lat":44.6,"lng":22,"year":8000},{"name":"Carpathian Basin","lat":47,"lng":19,"year":7600},{"name":"Central Germany","lat":51,"lng":11,"year":7400},{"name":"Paris Basin","lat":49,"lng":2.5,"year":7000},{"name":"Britain","lat":51.5,"lng":-1.5,"year":6000}]'::jsonb, null, '{"count":1500,"clusterCount":6,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'Arrival dates vary by region within a few centuries. Farmers mixed with local hunter-gatherers to different degrees.', 'Central Anatolia', 'Northwest Europe', array['Thrace', 'Iron Gates', 'Carpathian Basin', 'Central Germany']::text[], 'Overland via the Balkans and up the Danube (Linearbandkeramik), then west to the Paris Basin and Britain.', 'Farmers descended from Aegean and Anatolian populations brought agriculture into central and northern Europe.', 'Neolithic farmers of Anatolian ancestry (Starčevo–Körös, then Linearbandkeramik).', 'The early and middle Holocene, warm and stable.', 'Farmer ancestry forms a large share of present-day European ancestry.', '{"lat":46,"lng":15,"distance":2.6}'::jsonb),
  ('neolithic-cardial', 18, 'homo-sapiens', 'First farmers: Mediterranean route', 'Neolithic expansion', '[{"name":"Çatalhöyük","lat":37.67,"lng":32.83,"year":9500},{"name":"Aegean","lat":38.5,"lng":25.5,"year":8600},{"name":"Thessaly","lat":39.5,"lng":22.5,"year":8400},{"name":"Adriatic","lat":42,"lng":16,"year":8000},{"name":"Southern Italy","lat":40.5,"lng":17,"year":7800},{"name":"Southern France","lat":43.3,"lng":4,"year":7600},{"name":"Valencia","lat":39,"lng":-0.5,"year":7500},{"name":"Portugal","lat":38.7,"lng":-9,"year":7400}]'::jsonb, null, '{"count":1300,"clusterCount":5,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'Spread by sea along the coasts is likely but the exact hops are unknown. Hunter-gatherer admixture was higher here than in central Europe.', 'Central Anatolia', 'Iberia', array['Aegean', 'Thessaly', 'Adriatic', 'Southern France']::text[], 'Coastal, largely maritime spread associated with Impressa and Cardial pottery.', 'A second stream of farmers spread along the northern Mediterranean coasts to Iberia.', 'Neolithic farmers of Aegean ancestry who mixed with local hunter-gatherers.', 'Rapid coastal colonisation by boat.', 'Brought farming to the western Mediterranean within a few centuries.', '{"lat":40,"lng":12,"distance":2.6}'::jsonb),
  ('steppe-west', 19, 'homo-sapiens', 'Steppe herders into Europe', 'Bronze Age expansion', '[{"name":"Pontic–Caspian steppe","lat":47.5,"lng":40,"year":5300},{"name":"Lower Danube","lat":44.5,"lng":27,"year":4900},{"name":"Carpathian Basin","lat":47,"lng":20,"year":4800},{"name":"Central Germany","lat":51.5,"lng":12,"year":4600},{"name":"Rhineland","lat":50.5,"lng":7,"year":4500},{"name":"Britain","lat":52,"lng":-1.5,"year":4400},{"name":"Iberia","lat":40.5,"lng":-4,"year":4300}]'::jsonb, null, '{"count":1400,"clusterCount":6,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'Ancient DNA establishes the movement of people. That it carried Indo-European languages is an inference.', 'Pontic–Caspian steppe', 'Western Europe', array['Lower Danube', 'Carpathian Basin', 'Central Europe', 'Rhineland', 'Britain']::text[], 'Drawn west from the steppe (Yamnaya) through Corded Ware and Bell Beaker regions.', 'Herders with Yamnaya-related ancestry spread across Europe and transformed its population.', 'Yamnaya-related herders and their descendants in the Corded Ware and Bell Beaker groups.', 'Wheeled vehicles, horse use and herding economies on the steppe.', 'Steppe ancestry is a major part of present-day European ancestry.', '{"lat":49,"lng":18,"distance":2.6}'::jsonb),
  ('steppe-east-afanasievo', 20, 'homo-sapiens', 'Steppe herders east to the Altai', 'Bronze Age expansion', '[{"name":"Volga–Ural","lat":52,"lng":50,"year":5300},{"name":"Kazakh steppe","lat":50,"lng":68,"year":5100},{"name":"Altai","lat":51,"lng":86,"year":5000},{"name":"Minusinsk Basin","lat":53.7,"lng":91.7,"year":4900}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'The genetic match between Yamnaya and Afanasievo is close. A link to the Tocharian languages is speculative.', 'Volga–Ural steppe', 'Altai and Minusinsk Basin', array['Kazakh steppe']::text[], 'Straight across the steppe belt, ~2,000 km in a few centuries.', 'Yamnaya-related herders crossed the steppe to the Altai, founding the Afanasievo culture.', 'Afanasievo herders, genetically almost identical to Yamnaya.', 'Mobile pastoralism with wagons.', 'One of the fastest long-distance migrations in prehistory.', '{"lat":51,"lng":70,"distance":2.5}'::jsonb),
  ('steppe-to-south-asia', 21, 'homo-sapiens', 'Steppe ancestry into South Asia', 'Bronze Age expansion', '[{"name":"Sintashta, Southern Urals","lat":52.5,"lng":60,"year":4100},{"name":"Kazakhstan (Andronovo)","lat":48,"lng":70,"year":3800},{"name":"Bactria–Margiana","lat":37.5,"lng":62,"year":3700},{"name":"Swat Valley","lat":35,"lng":72.5,"year":3500},{"name":"Punjab","lat":30,"lng":75,"year":3300}]'::jsonb, null, '{"count":800,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'Genetic arrival in the first half of the 2nd millennium BCE is secure; the link to Indo-Aryan languages is an inference.', 'Southern Urals', 'Northwest South Asia', array['Kazakh steppe', 'Bactria–Margiana', 'Swat Valley']::text[], 'South from the steppe through Central Asia and the northwestern passes.', 'People with steppe ancestry moved into South Asia after the Indus civilisation declined.', 'Descendants of Sintashta–Andronovo herders.', 'The late Bronze Age, after the decline of the Harappan cities.', 'Steppe ancestry forms part of the ancestry of many present-day South Asians.', '{"lat":42,"lng":66,"distance":2.6}'::jsonb),
  ('magdalenian-recolonisation', 22, 'homo-sapiens', 'Recolonising Europe after the Ice Age', 'Late Glacial', '[{"name":"Cantabria","lat":43.3,"lng":-4,"year":19000},{"name":"Dordogne","lat":45,"lng":1,"year":17000},{"name":"Paris Basin","lat":48.5,"lng":2.5,"year":15500},{"name":"Rhineland","lat":50.5,"lng":7.5,"year":15000},{"name":"Central Germany","lat":51,"lng":11.5,"year":14800},{"name":"Southern Britain","lat":51.28,"lng":-2.77,"year":14700}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'The genetic cluster and the sites are secure; the route between them is illustrative.', 'Franco-Cantabrian refuge', 'Northern Europe', array['Dordogne', 'Paris Basin', 'Rhineland']::text[], 'North out of the Ice Age refuge of northern Spain and southwest France.', 'Magdalenian hunters spread north from their refuge as the ice sheets retreated.', 'Hunter-gatherers of the Magdalenian culture (''GoyetQ2'' ancestry).', 'Warming after the Last Glacial Maximum; reindeer and horse herds moved north.', 'Repopulated northern Europe after the coldest phase of the last ice age.', '{"lat":47,"lng":3,"distance":2.2}'::jsonb),
  ('epigravettian-villabruna', 23, 'homo-sapiens', 'Villabruna hunters spread across Europe', 'Late Glacial', '[{"name":"Balkans","lat":43,"lng":21,"year":16000},{"name":"Northern Italy","lat":46.1,"lng":11.9,"year":14000},{"name":"Western Alps","lat":45.5,"lng":5,"year":13500},{"name":"Low Countries","lat":51,"lng":4.5,"year":13000},{"name":"Britain","lat":52,"lng":-1,"year":12000}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'The genetic turnover is clear; its source in southeastern Europe and the route are approximate.', 'Balkans', 'Northwest Europe', array['Northern Italy', 'Alps', 'Low Countries']::text[], 'From the Balkans along the southern Alps, then north.', 'From ~14,000 years ago a new ancestry from southeastern Europe spread across the continent.', 'Epigravettian hunter-gatherers (''Villabruna'' ancestry).', 'The warm Bølling–Allerød interval.', 'Largely replaced Magdalenian-associated ancestry; ancestors of later Western hunter-gatherers.', '{"lat":47,"lng":10,"distance":2.2}'::jsonb),
  ('neolithic-mainland-sea', 24, 'homo-sapiens', 'Farmers into mainland Southeast Asia', 'Neolithic expansion', '[{"name":"Middle Yangtze","lat":30,"lng":112,"year":6000},{"name":"Lingnan","lat":23,"lng":113,"year":5000},{"name":"Northern Vietnam (Man Bac)","lat":20.2,"lng":105.9,"year":4000},{"name":"Northeast Thailand","lat":17.4,"lng":103.2,"year":3800},{"name":"Cambodia","lat":12.5,"lng":104.5,"year":3500},{"name":"Malay Peninsula","lat":5,"lng":101.5,"year":3000}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'There were several waves (Neolithic, then Bronze Age). Paths between sites are illustrative.', 'Yangtze basin', 'Malay Peninsula', array['Lingnan', 'Northern Vietnam', 'Thailand', 'Cambodia']::text[], 'South from the rice-farming Yangtze region into mainland Southeast Asia.', 'Farmers with southern Chinese ancestry spread rice and millet farming into Southeast Asia.', 'Neolithic farmers who mixed with local Hòabìnhian hunter-gatherers.', 'Rice and millet farming and pottery spreading south.', 'Shaped the ancestry of most present-day mainland Southeast Asians.', '{"lat":18,"lng":106,"distance":2.4}'::jsonb),
  ('austronesian-near-oceania', 25, 'homo-sapiens', 'Out of Taiwan to Lapita', 'Austronesian expansion', '[{"name":"Taiwan","lat":23.5,"lng":121,"year":5000},{"name":"Batanes","lat":20.45,"lng":121.97,"year":4200},{"name":"Luzon","lat":17.5,"lng":121.5,"year":4000},{"name":"Sulawesi & Moluccas","lat":-1,"lng":124,"year":3500},{"name":"Bismarck Archipelago","lat":-3.5,"lng":151.5,"year":3300},{"name":"Vanuatu (Teouma)","lat":-17.75,"lng":168.4,"year":2900},{"name":"Fiji","lat":-18,"lng":178,"year":2900},{"name":"Tonga","lat":-21.2,"lng":-175.2,"year":2850},{"name":"Samoa","lat":-13.8,"lng":-172,"year":2800}]'::jsonb, null, '{"count":1500,"clusterCount":6,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'The Taiwan-to-Philippines dates are approximate. Some Philippine groups split earlier, which complicates a simple out-of-Taiwan model. The first Lapita people had almost no Papuan ancestry.', 'Taiwan', 'West Polynesia (Samoa)', array['Philippines', 'Sulawesi', 'Bismarck Archipelago', 'Vanuatu', 'Fiji', 'Tonga']::text[], 'By sea from Taiwan through the Philippines and eastern Indonesia to the Bismarcks, then into Remote Oceania.', 'Austronesian-speaking seafarers spread from Taiwan into the Pacific, reaching Remote Oceania ~3,000 years ago.', 'Austronesian-speaking farmers and sailors; in Oceania, the makers of Lapita pottery.', 'Outrigger canoes, pottery and domestic pigs, dogs and chickens.', 'The first people to settle Remote Oceania.', '{"lat":0,"lng":150,"distance":3.3}'::jsonb),
  ('polynesia-remote', 26, 'homo-sapiens', 'East Polynesia: Hawai''i, Rapa Nui, Aotearoa', 'Austronesian expansion', '[{"name":"Samoa","lat":-13.8,"lng":-172,"year":2800},{"name":"Society Islands","lat":-17.5,"lng":-149.5,"year":950},{"name":"Marquesas","lat":-9,"lng":-140,"year":850},{"name":"Hawai''i","lat":19.6,"lng":-155.5,"year":750}]'::jsonb, '[{"id":"rapa-nui","name":"Rapa Nui","fromWaypoint":1,"share":0.3,"path":[{"name":"Mangareva","lat":-23.1,"lng":-134.97,"year":825},{"name":"Rapa Nui","lat":-27.1,"lng":-109.35,"year":750}],"note":"Rapa Nui was settled ~AD 1200; its people met Native Americans between ~AD 1250 and 1430."},{"id":"aotearoa","name":"Aotearoa New Zealand","fromWaypoint":1,"share":0.3,"path":[{"name":"Cook & Austral Islands","lat":-21,"lng":-159.8,"year":850},{"name":"Aotearoa","lat":-41.5,"lng":173.9,"year":750}],"note":"New Zealand was settled ~AD 1250–1300, the last major land mass reached by people."}]'::jsonb, '{"count":1300,"clusterCount":5,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'A ~1,800-year pause in West Polynesia preceded rapid settlement of East Polynesia from ~AD 1025. All three branches are drawn arriving ~750 years ago; Hawai''i may be somewhat earlier and Aotearoa slightly later (~AD 1280).', 'Samoa', 'Hawai''i, Rapa Nui and Aotearoa', array['Society Islands', 'Marquesas', 'Mangareva', 'Cook Islands']::text[], 'From West Polynesia to the Society Islands, then branching to the three corners of the Polynesian Triangle.', 'After a long pause, Polynesian voyagers settled the remote islands of East Polynesia within a few centuries.', 'Polynesian navigators, descended from Lapita settlers.', 'Double-hulled voyaging canoes and non-instrument navigation.', 'The last great expansion of humans into unpopulated land.', '{"lat":-15,"lng":-150,"distance":3.6}'::jsonb),
  ('austronesian-madagascar', 27, 'homo-sapiens', 'Across the Indian Ocean to Madagascar', 'Austronesian expansion', '[{"name":"Southeast Borneo","lat":-2.5,"lng":114.5,"year":1600},{"name":"Java","lat":-6.5,"lng":106.5,"year":1550},{"name":"Indian Ocean","lat":-5,"lng":80,"year":1480},{"name":"Comoros","lat":-11.7,"lng":43.3,"year":1400},{"name":"Northwest Madagascar","lat":-15.7,"lng":46.3,"year":1300}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'The ocean route is unknown: a direct crossing and a coastal route via South Asia and East Africa are both proposed. Settlement before the mid-1st millennium AD is not supported.', 'Southeast Borneo', 'Madagascar', array['Java', 'Indian Ocean', 'Comoros']::text[], 'Drawn as a direct Indian Ocean crossing; the actual route is debated.', 'Austronesian seafarers from Indonesia settled Madagascar, where they mixed with Bantu-speaking Africans.', 'Austronesian-speaking voyagers from the Barito region of Borneo and their descendants.', 'Monsoon-driven Indian Ocean trade networks.', 'The westernmost reach of the Austronesian expansion.', '{"lat":-10,"lng":75,"distance":3.4}'::jsonb),
  ('paleo-inuit', 28, 'homo-sapiens', 'Paleo-Inuit across the Arctic', 'Holocene Arctic dispersal', '[{"name":"Chukotka","lat":66,"lng":-172,"year":5500},{"name":"Western Alaska","lat":64.5,"lng":-162,"year":5000},{"name":"Victoria Island","lat":69,"lng":-110,"year":4800},{"name":"Ellesmere Island","lat":78,"lng":-80,"year":4600},{"name":"Disko Bay, Greenland","lat":68.8,"lng":-51.5,"year":4400}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'The genetic picture is clear; the exact path across the islands is illustrative.', 'Chukotka', 'Greenland', array['Alaska', 'Canadian Arctic Archipelago', 'Ellesmere']::text[], 'East across the Arctic from Bering Strait to Greenland.', 'Paleo-Inuit (Saqqaq, later Dorset) peoples crossed the North American Arctic to Greenland.', 'Paleo-Inuit, one source population that persisted for over 4,000 years.', 'The mid-Holocene Arctic, with musk ox, caribou and seals.', 'The first people in the eastern Arctic; their ancestry also contributes to Na-Dene speakers.', '{"lat":70,"lng":-110,"distance":3}'::jsonb),
  ('thule-inuit', 29, 'homo-sapiens', 'Thule (Inuit) migration', 'Late Holocene Arctic', '[{"name":"Bering Strait","lat":65.6,"lng":-168,"year":800},{"name":"Northern Alaska","lat":71,"lng":-156,"year":780},{"name":"Amundsen Gulf","lat":70,"lng":-124,"year":750},{"name":"Central Arctic","lat":69,"lng":-95,"year":740},{"name":"Smith Sound","lat":78.5,"lng":-73,"year":720},{"name":"Northwest Greenland","lat":77.5,"lng":-69,"year":700}]'::jsonb, null, '{"count":800,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'The migration was rapid in the 13th century AD; an older model of ~AD 1000 is rejected.', 'Bering Strait', 'Greenland', array['Northern Alaska', 'Canadian Arctic', 'Smith Sound']::text[], 'Along the Arctic coast from Alaska to Greenland.', 'The ancestors of today''s Inuit moved rapidly from Alaska to Greenland, replacing the Paleo-Inuit.', 'Thule culture, ancestors of present-day Inuit.', 'Skin boats, dog sleds and whale hunting.', 'Established the Inuit across the Arctic.', '{"lat":72,"lng":-110,"distance":3}'::jsonb),
  ('norse-north-atlantic', 30, 'homo-sapiens', 'Norse across the North Atlantic', 'Historic', '[{"name":"Western Norway","lat":60.4,"lng":5.3,"year":1150},{"name":"Faroe Islands","lat":62,"lng":-6.8,"year":1100},{"name":"Iceland","lat":64.1,"lng":-21.9,"year":1075},{"name":"Greenland (Eastern Settlement)","lat":61.1,"lng":-45.5,"year":1015},{"name":"L''Anse aux Meadows","lat":51.6,"lng":-55.53,"year":979}]'::jsonb, null, '{"count":600,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'Iceland (~AD 870) and Greenland (~AD 985) come from written sources and archaeology; Newfoundland is fixed at AD 1021.', 'Norway', 'Newfoundland', array['Faroes', 'Iceland', 'Greenland']::text[], 'Island by island across the North Atlantic.', 'Norse seafarers settled Iceland and Greenland and briefly reached North America.', 'Norse settlers from Scandinavia.', 'The Medieval Warm Period.', 'The first documented Europeans in the Americas.', '{"lat":60,"lng":-25,"distance":2.8}'::jsonb),
  ('caribbean-archaic', 31, 'homo-sapiens', 'Caribbean: first settlers', 'Holocene island colonisation', '[{"name":"Northeast Venezuela","lat":10.5,"lng":-63,"year":7500},{"name":"Trinidad","lat":10.5,"lng":-61.3,"year":7000},{"name":"Cuba","lat":22,"lng":-79.5,"year":6000},{"name":"Hispaniola","lat":19,"lng":-71,"year":5800},{"name":"Puerto Rico","lat":18.2,"lng":-66.5,"year":5000}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'The Greater Antilles were reached before the southern islands. Whether the first settlers came from South or Central America is debated; the path is illustrative.', 'Northern South America', 'Greater Antilles', array['Trinidad', 'Cuba', 'Hispaniola']::text[], 'Drawn as a direct open-water crossing to the Greater Antilles.', 'Archaic-age foragers settled the larger Caribbean islands first.', 'Archaic-age foragers from the American mainland.', 'Mid-Holocene seas near present levels.', 'The first people in the Caribbean islands.', '{"lat":17,"lng":-70,"distance":2.3}'::jsonb),
  ('caribbean-ceramic', 32, 'homo-sapiens', 'Caribbean: Ceramic Age farmers', 'Holocene island colonisation', '[{"name":"Orinoco","lat":8.5,"lng":-63.5,"year":2700},{"name":"Lesser Antilles","lat":15,"lng":-61.3,"year":2500},{"name":"Puerto Rico","lat":18.2,"lng":-66.5,"year":2400},{"name":"Hispaniola","lat":19,"lng":-71,"year":2000},{"name":"Bahamas","lat":24,"lng":-76,"year":1200}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Exact dates vary by island; the later Bahamas arrival is approximate.', 'Orinoco basin', 'Bahamas', array['Lesser Antilles', 'Puerto Rico', 'Hispaniola']::text[], 'Up the island chain from South America.', 'Pottery-making farmers from South America spread through the Caribbean, largely replacing earlier people.', 'Ceramic Age farmers, ancestors of the Taíno.', 'Manioc farming and pottery.', 'Ancestors of the people Columbus encountered in 1492.', '{"lat":17,"lng":-68,"distance":2.3}'::jsonb),
  ('south-america-interior', 33, 'homo-sapiens', 'Into the Andes and eastern South America', 'Terminal Pleistocene', '[{"name":"Isthmus of Panama","lat":8.5,"lng":-80,"year":15000},{"name":"Colombia","lat":4.5,"lng":-74,"year":14000},{"name":"Amazon margin","lat":-5,"lng":-60,"year":12000},{"name":"Lagoa Santa, Brazil","lat":-19.6,"lng":-43.9,"year":10500}]'::jsonb, '[{"id":"andes","name":"Andes","fromWaypoint":1,"share":0.45,"path":[{"name":"Central Andes","lat":-13.5,"lng":-72,"year":12000},{"name":"Southern Andes","lat":-25,"lng":-67,"year":10500}],"note":"Highland settlement; regional Andean structure emerges by ~5,800 years ago."}]'::jsonb, '{"count":1000,"clusterCount":4,"spreadKm":90,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Genomes show at least two early streams and a later turnover ~9,000 years ago; the paths are interpolated. This complements the Pacific coastal route.', 'Central America', 'Eastern Brazil and the Andes', array['Colombia', 'Amazon margin', 'Central Andes']::text[], 'Inland branches from northern South America east to Brazil and south along the Andes.', 'People spread through the interior of South America, into the Andes and the eastern highlands.', 'Early South American hunter-gatherers, including a stream related to Clovis-associated ancestry.', 'The end of the last ice age.', 'Shows the peopling of South America involved several streams, not one.', '{"lat":-10,"lng":-62,"distance":3}'::jsonb),
  ('erectus-out-of-africa', 34, 'homo-erectus', 'Out of Africa I: to the Caucasus', 'Early Homo dispersal', '[{"name":"West Turkana","lat":4,"lng":35.8,"year":1900000},{"name":"Nile valley","lat":24,"lng":32.9,"year":1885000},{"name":"Sinai","lat":30,"lng":33.8,"year":1875000},{"name":"Jordan Valley (''Ubeidiya)","lat":32.69,"lng":35.56,"year":1870000},{"name":"Eastern Anatolia","lat":38.5,"lng":40,"year":1860000},{"name":"Dmanisi","lat":41.34,"lng":44.34,"year":1850000}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'high', 'illustrative', 'Dmanisi (1.85–1.78 million years) is secure. The corridor (Sinai or Bab-el-Mandeb) is unknown, and the age of ''Ubeidiya is contested. Stone tools at Shangchen, China (~2.1 million years) show some hominins had left Africa even earlier.', 'East Africa', 'Southern Caucasus (Dmanisi)', array['Nile valley', 'Sinai', 'Levant', 'Eastern Anatolia']::text[], 'Drawn up the Nile and through the Levant to the Caucasus; the corridor is illustrative.', 'Early Homo erectus left Africa and reached Dmanisi in Georgia ~1.85 million years ago.', 'Small-brained early Homo erectus (sometimes called H. georgicus at Dmanisi), with simple Oldowan-like tools.', 'Early Pleistocene grasslands and open woodland across Africa and western Asia.', 'The first well-dated hominins outside Africa.', '{"lat":30,"lng":38,"distance":2.6}'::jsonb),
  ('erectus-east-asia', 35, 'homo-erectus', 'Early Homo to China', 'Early Homo dispersal', '[{"name":"Dmanisi","lat":41.34,"lng":44.34,"year":1800000},{"name":"Iranian Plateau","lat":35.5,"lng":53,"year":1770000},{"name":"Central Asia","lat":39.5,"lng":66,"year":1740000},{"name":"Hexi Corridor","lat":38.5,"lng":101,"year":1680000},{"name":"Gongwangling (Lantian)","lat":34.2,"lng":109.5,"year":1630000}]'::jsonb, null, '{"count":800,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Site dates are secure; there are no sites along the Central Asian corridor, so the path is inferred. The older Shangchen tools (~2.1 million years) mean hominins reached China earlier than this route shows; their maker is unknown.', 'Caucasus', 'Loess Plateau, China', array['Iranian Plateau', 'Central Asia', 'Hexi Corridor']::text[], 'Drawn across the interior of Asia; illustrative.', 'Homo erectus spread across Asia and was on the Loess Plateau by ~1.63 million years ago.', 'Homo erectus; later populations include ''Peking Man'' at Zhoukoudian.', 'Alternating glacial loess and warmer soils on the Loess Plateau.', 'Homo erectus lived in East Asia for well over a million years.', '{"lat":38,"lng":80,"distance":3}'::jsonb),
  ('erectus-south-asia', 36, 'homo-erectus', 'Acheulean toolmakers to India', 'Early Homo dispersal', '[{"name":"Levant","lat":32.7,"lng":35.5,"year":1800000},{"name":"Arabian interior","lat":24,"lng":46,"year":1700000},{"name":"Makran & Indus","lat":25.5,"lng":66.5,"year":1620000},{"name":"Thar margin","lat":24.5,"lng":73.5,"year":1560000},{"name":"Attirampakkam","lat":13.23,"lng":79.89,"year":1510000}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Attirampakkam has a pooled age of ~1.51 million years but a minimum of ~1.07 million. There are no Early Pleistocene fossils in India. Older claims at Masol (~2.6 million) are contested and not drawn.', 'Levant', 'South India', array['Arabia', 'Makran', 'Indus']::text[], 'Illustrative path across Arabia and along the Makran coast.', 'Acheulean handaxe makers reached South India about 1.5 million years ago.', 'Probably Homo erectus; no fossils are known.', 'Humid phases opened corridors across Arabia.', 'Shows the Acheulean spread out of Africa early.', '{"lat":23,"lng":62,"distance":2.7}'::jsonb),
  ('erectus-sundaland', 37, 'homo-erectus', 'Homo erectus to Java', 'Early Homo dispersal', '[{"name":"Yuanmou","lat":25.7,"lng":101.87,"year":1700000},{"name":"Northern Vietnam & Laos","lat":21,"lng":104.5,"year":1550000},{"name":"Malay Peninsula","lat":5,"lng":101.5,"year":1450000},{"name":"Sunda Shelf","lat":-2,"lng":106,"year":1380000},{"name":"Sangiran","lat":-7.45,"lng":110.83,"year":1300000}]'::jsonb, null, '{"count":800,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Java''s dates are secure; there are no mainland sites to fix the path before ~0.8 million years. Homo erectus survived on Java until ~117,000–108,000 years ago (Ngandong).', 'Southwest China', 'Java', array['Indochina', 'Malay Peninsula', 'Sunda Shelf']::text[], 'Drawn south over the exposed Sunda Shelf; illustrative.', 'Homo erectus reached Java by ~1.3 million years ago, walking across land exposed by low seas.', 'Homo erectus (''Java Man'').', 'Glacial low seas joined Java, Sumatra and Borneo to the mainland.', 'Java holds the longest record of Homo erectus, which lasted there until ~110,000 years ago.', '{"lat":8,"lng":106,"distance":2.7}'::jsonb),
  ('erectus-europe', 38, 'homo-erectus', 'Early Homo into Europe', 'Early Homo dispersal', '[{"name":"Dmanisi","lat":41.34,"lng":44.34,"year":1800000},{"name":"Northern Black Sea","lat":46.5,"lng":32,"year":1500000},{"name":"Korolevo","lat":48.15,"lng":23.13,"year":1420000},{"name":"Pirro Nord","lat":41.8,"lng":15.4,"year":1400000},{"name":"Barranco León (Orce)","lat":37.72,"lng":-2.48,"year":1380000},{"name":"Sima del Elefante (Atapuerca)","lat":42.35,"lng":-3.52,"year":1150000}]'::jsonb, null, '{"count":900,"clusterCount":4,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Korolevo supports an east-to-west entry, but whether people went north or south of the Black Sea is unknown. Pirro Nord''s date is broad. The Atapuerca face is only tentatively assigned (Homo aff. erectus). Later Europeans at Gran Dolina (~850,000) are a separate species, Homo antecessor.', 'Caucasus', 'Iberia', array['Northern Black Sea', 'Carpathians', 'Italy']::text[], 'Drawn east to west across southern Europe.', 'Early Homo spread east to west across southern Europe from ~1.4 million years ago.', 'Early Homo, probably related to Homo erectus; later Homo antecessor in Spain.', 'Mild interglacials in southern Europe, with a fauna of African and Asian origin.', 'The first peopling of Europe.', '{"lat":44,"lng":18,"distance":2.7}'::jsonb),
  ('floresiensis-to-flores', 39, 'homo-floresiensis', 'Across the Wallace Line to Flores', 'Island hominins', '[{"name":"Sangiran","lat":-7.45,"lng":110.83,"year":1300000},{"name":"Bali","lat":-8.4,"lng":115.2,"year":1150000},{"name":"Lombok","lat":-8.6,"lng":116.3,"year":1100000},{"name":"Sumbawa","lat":-8.6,"lng":118,"year":1050000},{"name":"Wolo Sege","lat":-8.65,"lng":121.1,"year":1020000}]'::jsonb, null, '{"count":600,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Who reached Flores is debated: early Javanese Homo erectus that became small on the island, or an older lineage. A source on Sulawesi is also possible: tools there are at least 1.04 million years old. The route is illustrative and shows the ancestors of H. floresiensis, not the species itself.', 'Java', 'Flores', array['Bali', 'Lombok', 'Sumbawa']::text[], 'Island hopping east across the Lesser Sunda Islands, crossing deep water east of Bali.', 'Hominins crossed the sea to Flores ~1 million years ago; their descendants became Homo floresiensis.', 'Ancestors of Homo floresiensis, possibly early Javanese Homo erectus.', 'Even at low sea levels, Lombok and Flores were never joined to Asia.', 'Shows that early hominins crossed sea barriers and evolved in isolation on islands.', '{"lat":-8,"lng":117,"distance":2}'::jsonb),
  ('luzonensis-to-luzon', 40, 'homo-luzonensis', 'Hominins reach Luzon', 'Island hominins', '[{"name":"Northern Borneo","lat":6,"lng":116.5,"year":800000},{"name":"Palawan","lat":9.8,"lng":118.7,"year":780000},{"name":"Mindoro","lat":12.9,"lng":121.1,"year":750000},{"name":"Kalinga site","lat":17.5,"lng":121.4,"year":709000}]'::jsonb, null, '{"count":500,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'low', 'illustrative', 'The source is unknown: from Borneo via Palawan (drawn), from Sulawesi via Mindanao, or from Taiwan. The 709,000-year-old Kalinga tools have no fossils, so their makers may or may not be ancestors of Homo luzonensis.', 'Borneo', 'Luzon', array['Palawan', 'Mindoro']::text[], 'One of three proposed routes; drawn via Palawan and Mindoro.', 'Hominins crossed the sea to Luzon by ~709,000 years ago; Homo luzonensis lived there ~67,000–50,000 years ago.', 'Unknown toolmakers; later Homo luzonensis.', 'Luzon was never joined to the Asian mainland.', 'A second case of an island hominin lineage in Southeast Asia.', '{"lat":13,"lng":120,"distance":2.1}'::jsonb),
  ('neanderthal-levant', 41, 'homo-neanderthalensis', 'Neanderthals into the Levant', 'Neanderthal expansion', '[{"name":"Balkans","lat":42.5,"lng":22,"year":135000},{"name":"Anatolia","lat":38.5,"lng":33,"year":128000},{"name":"Tabun","lat":32.67,"lng":34.97,"year":122000},{"name":"Amud","lat":32.87,"lng":35.5,"year":60000},{"name":"Kebara","lat":32.56,"lng":34.94,"year":55000}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'The Tabun C1 age is uncertain (~143,000–112,000 years). Neanderthals may have arrived in more than one pulse; the path from Europe is illustrative.', 'Southeastern Europe', 'Southern Levant', array['Anatolia']::text[], 'Through Anatolia into the Levant.', 'Neanderthals expanded from Europe into the Levant, where they met Homo sapiens.', 'Neanderthals.', 'The Levant alternated between Homo sapiens and Neanderthal occupation.', 'The Levant is the likeliest region of the interbreeding found in all non-Africans.', '{"lat":36,"lng":32,"distance":2.1}'::jsonb),
  ('neanderthal-central-asia', 42, 'homo-neanderthalensis', 'Neanderthals to the Zagros and Central Asia', 'Neanderthal expansion', '[{"name":"Eastern Anatolia","lat":38.5,"lng":40,"year":80000},{"name":"Shanidar","lat":36.83,"lng":44.22,"year":70000},{"name":"Kopet Dag","lat":38,"lng":57.5,"year":65000},{"name":"Teshik-Tash","lat":38.2,"lng":67,"year":60000},{"name":"Okladnikov","lat":51.8,"lng":84.5,"year":45000}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Teshik-Tash is poorly dated. mtDNA ties Teshik-Tash and Okladnikov to European Neanderthals, but the path between them is illustrative.', 'Anatolia', 'Altai', array['Zagros', 'Kopet Dag', 'Uzbekistan']::text[], 'East through the Zagros and Central Asian foothills, then north to the Altai.', 'Neanderthals lived as far east as Uzbekistan and the Altai.', 'Neanderthals.', 'Mountain foothills with rich game.', 'Neanderthals'' range reached deep into Asia.', '{"lat":42,"lng":62,"distance":2.7}'::jsonb),
  ('neanderthal-altai-first', 43, 'homo-neanderthalensis', 'First Neanderthals in the Altai', 'Neanderthal expansion', '[{"name":"Central Europe","lat":48.5,"lng":15,"year":150000},{"name":"Northern Black Sea","lat":47,"lng":35,"year":140000},{"name":"North Caucasus","lat":45,"lng":45,"year":135000},{"name":"Kazakh steppe","lat":49,"lng":70,"year":128000},{"name":"Denisova Cave","lat":51.4,"lng":84.68,"year":120000}]'::jsonb, null, '{"count":700,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Inferred from genomes: the Altai lineage split from European Neanderthals before ~120,000 years ago. The route is entirely inferred. This eastern population was later replaced by a second wave.', 'Europe', 'Altai', array['Black Sea steppe', 'North Caucasus', 'Kazakh steppe']::text[], 'An inferred path along the steppe belt.', 'An early wave of Neanderthals reached the Altai by ~120,000 years ago, where they met Denisovans.', 'Neanderthals (the population of Denisova 5).', 'The last interglacial.', 'Explains Neanderthal–Denisovan contact; Denisova 11 had a Neanderthal mother and Denisovan father.', '{"lat":48,"lng":55,"distance":3}'::jsonb),
  ('neanderthal-altai-second', 44, 'homo-neanderthalensis', 'Second Neanderthal wave to Siberia', 'Neanderthal expansion', '[{"name":"Vindija","lat":46.3,"lng":16.08,"year":100000},{"name":"Crimea","lat":45,"lng":34.3,"year":90000},{"name":"Mezmaiskaya","lat":44.17,"lng":40,"year":85000},{"name":"Lower Volga","lat":47,"lng":47,"year":82000},{"name":"Kazakh steppe","lat":50,"lng":72,"year":75000},{"name":"Chagyrskaya","lat":51.44,"lng":83.15,"year":59000}]'::jsonb, null, '{"count":800,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'medium', 'illustrative', 'Genomes and Micoquian tools agree on a source in Central and Eastern Europe. Timing is uncertain: the Chagyrskaya layers are ~59,000–49,000 years old, while genetic estimates place Chagyrskaya 8 nearer ~80,000.', 'Central Europe', 'Altai (Chagyrskaya)', array['Crimea', 'North Caucasus', 'Lower Volga', 'Kazakh steppe']::text[], 'Along the steppe from the Micoquian regions of Eastern Europe.', 'A later Neanderthal population from Eastern Europe moved to Siberia and replaced the earlier Altai Neanderthals.', 'Neanderthals with Micoquian tool kits.', 'The early last glacial period.', 'Shows Neanderthals moved over thousands of kilometres more than once.', '{"lat":48,"lng":50,"distance":3}'::jsonb),
  ('denisovan-tibet', 45, 'denisovans', 'Denisovans to the Tibetan Plateau', 'Denisovan dispersal', '[{"name":"Denisova Cave","lat":51.4,"lng":84.68,"year":200000},{"name":"Dzungarian Gate","lat":45.2,"lng":82.5,"year":185000},{"name":"Hexi Corridor","lat":39,"lng":99.5,"year":172000},{"name":"Baishiya Karst Cave","lat":35.45,"lng":102.57,"year":160000}]'::jsonb, null, '{"count":600,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'low', 'illustrative', 'Both sites are secure, but the direction could be the reverse: where Denisovans originated is unknown. Baishiya was used repeatedly, from ~160,000 to ~32,000 years ago.', 'Altai', 'Tibetan Plateau', array['Dzungaria', 'Hexi Corridor']::text[], 'Drawn from the Altai to the northeastern Tibetan Plateau; direction and corridor are illustrative.', 'Denisovans lived both in the Altai and at 3,280 m on the Tibetan Plateau.', 'Denisovans.', 'Middle and Late Pleistocene glacial cycles.', 'Denisovans adapted to high altitude; a variant of EPAS1 inherited from them helps present-day Tibetans.', '{"lat":43,"lng":92,"distance":2.6}'::jsonb),
  ('denisovan-northeast-asia', 46, 'denisovans', 'Denisovans in Northeast Asia (Harbin)', 'Denisovan dispersal', '[{"name":"Denisova Cave","lat":51.4,"lng":84.68,"year":200000},{"name":"Mongolian Plateau","lat":47.5,"lng":100,"year":180000},{"name":"Inner Mongolia","lat":46.5,"lng":115,"year":165000},{"name":"Harbin","lat":45.75,"lng":126.65,"year":146000}]'::jsonb, null, '{"count":600,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'low', 'illustrative', 'Harbin''s identification as Denisovan (2025) is strong; its age (at least ~146,000 years) and the route from the Altai are uncertain. The direction may be the reverse.', 'Altai', 'Northeast China', array['Mongolian Plateau', 'Inner Mongolia']::text[], 'Illustrative path across Mongolia.', 'Denisovans lived across northern Asia; the Harbin skull gives the first face of a Denisovan.', 'Denisovans (Harbin was first named Homo longi).', 'Cold Middle Pleistocene northern Asia.', 'Harbin shows what Denisovans looked like.', '{"lat":48,"lng":108,"distance":2.7}'::jsonb),
  ('denisovan-southeast-asia', 47, 'denisovans', 'Denisovans to Laos and Taiwan', 'Denisovan dispersal', '[{"name":"Baishiya Karst Cave","lat":35.45,"lng":102.57,"year":165000},{"name":"Sichuan Basin","lat":30.5,"lng":104,"year":158000},{"name":"Yunnan","lat":24.5,"lng":103,"year":150000},{"name":"Tam Ngu Hao 2, Laos","lat":20.2,"lng":103.4,"year":145000},{"name":"Guangdong coast","lat":22.5,"lng":113.5,"year":138000},{"name":"Penghu Channel","lat":23.5,"lng":119.8,"year":135000}]'::jsonb, null, '{"count":600,"clusterCount":3,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'low', 'illustrative', 'The Laos tooth (164,000–131,000) is dated; Penghu 1 may be ~190,000–130,000 or ~70,000–10,000 years old. The corridor is inferred.', 'Tibetan Plateau margin', 'Taiwan Strait', array['Sichuan', 'Yunnan', 'Northern Laos', 'Guangdong']::text[], 'South through Yunnan to Laos, then east along the South China coast; illustrative.', 'Denisovan fossils from Laos and the Taiwan Strait show they lived in tropical and coastal Asia too.', 'Denisovans.', 'The Penghu Channel was dry land when sea levels were low.', 'Denisovans occupied a wide range of environments, from Siberia to the tropics.', '{"lat":26,"lng":110,"distance":2.6}'::jsonb),
  ('denisovan-wallacea', 48, 'denisovans', 'Denisovans toward Wallacea and New Guinea', 'Denisovan dispersal', '[{"name":"Northern Laos","lat":20.2,"lng":103.4,"year":130000},{"name":"Malay Peninsula","lat":5,"lng":101.5,"year":110000},{"name":"Borneo","lat":0.5,"lng":114,"year":90000},{"name":"Sulawesi","lat":-2,"lng":120.5,"year":70000},{"name":"Moluccas","lat":0.5,"lng":128,"year":58000},{"name":"New Guinea","lat":-5.5,"lng":141,"year":50000}]'::jsonb, '[{"id":"luzon","name":"Luzon (Ayta ancestry)","fromWaypoint":2,"share":0.3,"path":[{"name":"Palawan","lat":9.8,"lng":118.7,"year":70000},{"name":"Luzon","lat":16,"lng":120.5,"year":50000}],"note":"The Philippine Ayta carry an independent pulse of Denisovan ancestry."}]'::jsonb, '{"count":1400,"clusterCount":6,"spreadKm":110,"edgeShare":0.3,"groupLengthKm":[70,170],"originSpreadKm":120,"speedVariation":0.08,"stagger":0.3,"splitGroups":1,"splitAt":0.5,"dispersalKm":{"north":160,"east":160}}'::jsonb, 'low', 'illustrative', 'No Denisovan fossils are known south of Laos. The path is inferred from Denisovan ancestry in Papuans and Philippine groups, which came from at least two deeply divergent Denisovan populations. Timing and route are illustrative.', 'Mainland Southeast Asia', 'New Guinea', array['Malay Peninsula', 'Borneo', 'Sulawesi', 'Moluccas']::text[], 'Drawn through Sundaland and Wallacea; based on genetics only.', 'Genetic evidence shows Denisovan groups lived somewhere near Wallacea, where they met the ancestors of Papuans.', 'At least two distinct Denisovan populations.', 'Glacial low seas exposed Sundaland and narrowed Wallacean crossings.', 'Papuans and Philippine Ayta carry the highest Denisovan ancestry today.', '{"lat":0,"lng":120,"distance":3}'::jsonb);
insert into public.route_evidence (route_id, position, type, description) values
  ('africa-levant', 0, 'archaeological', 'Homo sapiens burials at Skhul and Qafzeh (Israel), dated roughly 90,000–130,000 years ago.'),
  ('africa-levant', 1, 'archaeological', 'The Misliya Cave maxilla (~177,000–194,000 years ago) hints at even earlier, possibly intermittent, presence.'),
  ('africa-levant', 2, 'genetic', 'Most non-African ancestry traces to a later dispersal, so the genetic legacy of these early groups is unclear.'),
  ('out-of-africa-south', 0, 'genetic', 'Genome-wide data show most non-African populations derive from a dispersal roughly 50,000–70,000 years ago.'),
  ('out-of-africa-south', 1, 'genetic', 'The 45,000-year-old Ust''-Ishim genome dates Neanderthal admixture to roughly 50,000–60,000 years ago.'),
