insert into public.population_clusters (id, sort_order, species_id, region, lat, lng, lobes, start_bp, established_bp, end_bp, fade_years, growth_origin, color_from, visual_density, confidence, attested_bp, basis_note, land_only) values
  ('north-africa', 0, 'homo-sapiens', 'Northwest Africa', 32, -7, '[{"name":"Atlantic Morocco","lat":32,"lng":-7.5,"radiusKm":{"north":230,"east":300},"weight":1},{"name":"Middle Atlas","lat":34,"lng":-3,"radiusKm":{"north":160,"east":260},"weight":0.6},{"name":"Tell Atlas","lat":35.6,"lng":3.5,"radiusKm":{"north":110,"east":300},"weight":0.4}]'::jsonb, 320000, 300000, null, null, null, 'ancestral', 0.5, 'medium', 300000, 'Jebel Irhoud fossils (~315,000 years ago, with a wide dating range) are among the earliest known Homo sapiens and support a pan-African origin. Continuous occupation of the region is a simplification.', null),
  ('east-africa', 1, 'homo-sapiens', 'East Africa', 6.5, 37.5, '[{"name":"Ethiopian highlands","lat":8,"lng":38.5,"radiusKm":{"north":330,"east":280},"weight":1},{"name":"Afar & Middle Awash","lat":11,"lng":40.5,"radiusKm":{"north":180,"east":160},"weight":0.55},{"name":"Omo basin","lat":5,"lng":36,"radiusKm":{"north":170,"east":150},"weight":0.5},{"name":"Kenyan Rift","lat":0.5,"lng":36.5,"radiusKm":{"north":300,"east":200},"weight":0.8},{"name":"Tanzania","lat":-4.5,"lng":35.5,"radiusKm":{"north":280,"east":240},"weight":0.6},{"name":"Horn of Africa","lat":9.5,"lng":43.5,"radiusKm":{"north":180,"east":240},"weight":0.45}]'::jsonb, 320000, 300000, null, null, null, 'ancestral', 1, 'medium', 233000, 'Fossils from Omo Kibish (at least ~233,000 years ago) and Herto (~160,000) attest Homo sapiens here; presence before that is inferred from pan-African origin models. Groups left this region repeatedly while its populations continued.', null),
  ('southern-africa', 2, 'homo-sapiens', 'Southern Africa', -29, 25, '[{"name":"Highveld","lat":-27.5,"lng":27,"radiusKm":{"north":320,"east":360},"weight":1},{"name":"Southern Cape coast","lat":-33.6,"lng":22,"radiusKm":{"north":120,"east":360},"weight":0.8},{"name":"Limpopo","lat":-23.5,"lng":29.5,"radiusKm":{"north":220,"east":240},"weight":0.45}]'::jsonb, 320000, 300000, null, null, null, 'ancestral', 0.6, 'medium', 110000, 'Human remains from Klasies River (roughly 110,000 years ago) and later sites such as Blombos are generally attributed to Homo sapiens; earlier presence is inferred and the status of older fossils (e.g. Florisbad) is debated.', null),
  ('levant-early', 3, 'homo-sapiens', 'Southern Levant (early presence)', 32.6, 35.2, '[{"name":"Mount Carmel & Galilee","lat":32.7,"lng":35.2,"radiusKm":{"north":140,"east":70},"weight":1},{"name":"Jordan valley","lat":31.6,"lng":35.6,"radiusKm":{"north":110,"east":60},"weight":0.5},{"name":"Lebanon","lat":33.9,"lng":35.9,"radiusKm":{"north":100,"east":60},"weight":0.45}]'::jsonb, 104000, 90000, 66000, 14000, null, 'africa-levant', 0.42, 'medium', 100000, 'Skhul and Qafzeh fossils (~120,000–90,000 years ago) attest an early population. Whether it persisted is debated: the cluster fades because continuity is not demonstrated, not because a known extinction is modelled. Misliya (~180,000) shows an even earlier, probably short-lived presence that is not modelled.', null),
  ('southwest-asia', 4, 'homo-sapiens', 'Levant & Southwest Asia', 35, 37.5, '[{"name":"Levant","lat":33.5,"lng":36,"radiusKm":{"north":200,"east":110},"weight":1},{"name":"Northern Levant & Upper Euphrates","lat":36.4,"lng":38.3,"radiusKm":{"north":150,"east":230},"weight":0.8},{"name":"Upper Tigris & Zagros foothills","lat":36.8,"lng":43,"radiusKm":{"north":140,"east":230},"weight":0.5},{"name":"Negev","lat":30.8,"lng":34.9,"radiusKm":{"north":110,"east":80},"weight":0.35}]'::jsonb, 64000, 56000, null, null, null, 'ancestral', 0.62, 'medium', 54000, 'Manot Cave (~55,000 years ago) and Initial Upper Palaeolithic sites such as Boker Tachtit (~50,000) attest modern humans here. How this population relates to the southern dispersal is not modelled as a route; earlier presence in this phase is inferred.', null),
  ('south-asia', 5, 'homo-sapiens', 'Indian subcontinent', 21, 77.5, '[{"name":"Deccan","lat":20.5,"lng":77.5,"radiusKm":{"north":380,"east":360},"weight":1},{"name":"Gujarat & Thar margins","lat":24.5,"lng":71.5,"radiusKm":{"north":220,"east":280},"weight":0.5},{"name":"Southern India","lat":13,"lng":78,"radiusKm":{"north":280,"east":200},"weight":0.6},{"name":"Ganges plain","lat":25,"lng":83.5,"radiusKm":{"north":200,"east":380},"weight":0.5},{"name":"Sri Lanka","lat":7.6,"lng":80.7,"radiusKm":{"north":110,"east":70},"weight":0.2}]'::jsonb, 54000, 45000, null, null, '{"lat":24.8,"lng":67.8}'::jsonb, 'out-of-africa-south', 0.75, 'medium', 45000, 'Microlithic assemblages from roughly 48,000–45,000 years ago are usually linked to modern humans; fossils are later (Sri Lanka, ~38,000). Older Middle Palaeolithic tools such as Jwalapuram (~74,000) cannot be attributed to Homo sapiens with confidence. Approximate.', null),
  ('mainland-southeast-asia', 6, 'homo-sapiens', 'Mainland Southeast Asia', 18, 102.5, '[{"name":"Northern Laos & Thailand","lat":19,"lng":102.5,"radiusKm":{"north":320,"east":260},"weight":1},{"name":"Chao Phraya basin","lat":14.5,"lng":100.8,"radiusKm":{"north":240,"east":200},"weight":0.6},{"name":"Northern Vietnam","lat":21.5,"lng":105.3,"radiusKm":{"north":170,"east":180},"weight":0.45},{"name":"Mekong delta","lat":11.5,"lng":105.5,"radiusKm":{"north":160,"east":160},"weight":0.3}]'::jsonb, 68000, 61000, null, null, null, 'sunda-sahul', 0.55, 'low', 46000, 'Tam Pa Ling (Laos) attests modern humans by at least ~46,000 years ago, with some estimates considerably older. Earlier presence, and how people reached the region, are inferred and not modelled as a route.', null),
  ('sahul', 7, 'homo-sapiens', 'Sahul (Australia & New Guinea)', -13.5, 133.5, '[{"name":"Arnhem Land","lat":-13.8,"lng":133.5,"radiusKm":{"north":260,"east":420},"weight":1},{"name":"Kimberley","lat":-17,"lng":126,"radiusKm":{"north":260,"east":260},"weight":0.5},{"name":"New Guinea","lat":-5.8,"lng":142,"radiusKm":{"north":200,"east":450},"weight":0.65},{"name":"Cape York & interior","lat":-18.5,"lng":141,"radiusKm":{"north":380,"east":300},"weight":0.4},{"name":"Willandra Lakes","lat":-33.5,"lng":143.5,"radiusKm":{"north":220,"east":300},"weight":0.25}]'::jsonb, 47500, 39000, null, null, '{"lat":-10.5,"lng":134}'::jsonb, 'sunda-sahul', 0.75, 'medium', 47000, 'Occupation of Sahul by ~47,000–50,000 years ago is widely accepted; Madjedbebe''s ~65,000-year date is debated. Lake Mungo attests people in the southeast by ~42,000–38,000.', null),
  ('europe', 8, 'homo-sapiens', 'Europe', 46.5, 12, '[{"name":"Lower Danube & Balkans","lat":43.3,"lng":24.5,"radiusKm":{"north":220,"east":330},"weight":0.6},{"name":"Carpathian Basin","lat":46.8,"lng":19.5,"radiusKm":{"north":200,"east":300},"weight":0.65},{"name":"Upper Danube","lat":48.4,"lng":12.5,"radiusKm":{"north":180,"east":330},"weight":0.6},{"name":"France","lat":46,"lng":2.5,"radiusKm":{"north":330,"east":330},"weight":0.9},{"name":"Central European uplands","lat":50.8,"lng":10.5,"radiusKm":{"north":180,"east":380},"weight":0.4},{"name":"Italy","lat":42.5,"lng":13,"radiusKm":{"north":280,"east":110},"weight":0.3},{"name":"Iberia","lat":40.5,"lng":-4,"radiusKm":{"north":260,"east":320},"weight":0.35}]'::jsonb, 46000, 34000, null, null, '{"lat":43.3,"lng":25}'::jsonb, 'levant-europe', 0.85, 'high', 45000, 'Bacho Kiro (~46,000–44,000 years ago) attests early Homo sapiens in the Balkans; Upper Palaeolithic sites spread across Europe after that. Earlier incursions such as Grotte Mandrin (~54,000) are not shown as a persistent population.', null),
  ('caucasus', 9, 'homo-sapiens', 'Southern Caucasus', 41.8, 43.8, '[{"name":"Imereti & Kartli","lat":42.2,"lng":43.2,"radiusKm":{"north":90,"east":170},"weight":1},{"name":"Armenian Highlands","lat":40.4,"lng":44.4,"radiusKm":{"north":110,"east":150},"weight":0.7},{"name":"Kura valley","lat":41.4,"lng":46,"radiusKm":{"north":80,"east":140},"weight":0.4}]'::jsonb, 40000, 32500, null, null, '{"lat":40.2,"lng":44.4}'::jsonb, 'levant-caucasus', 0.5, 'medium', 38000, 'Upper Palaeolithic layers at Ortvale Klde (~42,000–38,000 years ago) and later Dzudzuana Cave attest modern humans in the southern Caucasus. Approximate.', null),
  ('northeast-siberia', 10, 'homo-sapiens', 'Northeast Siberia', 69.5, 134, '[{"name":"Yana basin","lat":70.4,"lng":135,"radiusKm":{"north":170,"east":380},"weight":1},{"name":"Verkhoyansk foothills","lat":67.5,"lng":131,"radiusKm":{"north":220,"east":300},"weight":0.5}]'::jsonb, 37000, 33000, null, null, null, 'beringia-americas', 0.42, 'medium', 32000, 'The Yana RHS site attests people in the Arctic by ~32,000 years ago. Earlier presence, and how people reached the region, are inferred and not modelled as a route.', null),
  ('beringia', 11, 'homo-sapiens', 'Beringia', 65.5, -160, '[{"name":"Chukotka","lat":66,"lng":173,"radiusKm":{"north":220,"east":380},"weight":0.6},{"name":"Western Alaska","lat":65,"lng":-158,"radiusKm":{"north":280,"east":450},"weight":1},{"name":"Yukon","lat":64.5,"lng":-140,"radiusKm":{"north":220,"east":300},"weight":0.4}]'::jsonb, 26000, 20000, null, null, null, 'beringia-americas', 0.42, 'low', null, 'Inferred mainly from genetic models (the ''Beringian standstill''); securely dated archaeology in eastern Beringia is younger (~14,000–15,000 years ago), and where the standstill population lived is debated. Much of the land bridge is now sea, so only present-day land is drawn.', null),
  ('north-america', 12, 'homo-sapiens', 'North America', 42, -105, '[{"name":"Pacific Northwest","lat":47.5,"lng":-121,"radiusKm":{"north":280,"east":220},"weight":0.6},{"name":"California","lat":37,"lng":-120,"radiusKm":{"north":330,"east":160},"weight":0.4},{"name":"Great Basin & Southwest","lat":37,"lng":-110,"radiusKm":{"north":330,"east":330},"weight":0.45},{"name":"Great Plains","lat":41,"lng":-98,"radiusKm":{"north":500,"east":500},"weight":0.8},{"name":"Eastern woodlands","lat":36,"lng":-85,"radiusKm":{"north":380,"east":420},"weight":0.5},{"name":"Mexico","lat":21,"lng":-101,"radiusKm":{"north":300,"east":380},"weight":0.4}]'::jsonb, 16500, 11000, null, null, '{"lat":52,"lng":-127}'::jsonb, 'beringia-americas', 0.85, 'medium', 15000, 'Sites such as Cooper''s Ferry and Paisley Caves attest people south of the ice sheets by roughly 16,000–14,000 years ago. The White Sands footprints (~23,000–21,000) would imply earlier presence but remain debated, so they are shown as a site only.', null),
  ('south-america', 13, 'homo-sapiens', 'South America', -15, -65, '[{"name":"Northern Andes","lat":4,"lng":-74.5,"radiusKm":{"north":380,"east":280},"weight":0.6},{"name":"Central Andes","lat":-11,"lng":-75.5,"radiusKm":{"north":550,"east":260},"weight":0.5},{"name":"Amazonia","lat":-5,"lng":-60,"radiusKm":{"north":500,"east":700},"weight":0.4},{"name":"Pampas","lat":-32,"lng":-62,"radiusKm":{"north":450,"east":400},"weight":0.4},{"name":"Southern Chile","lat":-40.5,"lng":-72.5,"radiusKm":{"north":400,"east":140},"weight":0.55}]'::jsonb, 15200, 9000, null, null, '{"lat":8.5,"lng":-77.5}'::jsonb, 'beringia-americas', 0.8, 'medium', 14500, 'Monte Verde (~14,500 years ago) attests people in southern South America; occupation spreads across the continent through the late Pleistocene and early Holocene.', null),
  ('afarensis-east-africa', 14, 'australopithecus-afarensis', 'East Africa (Australopithecus afarensis)', 7, 38.5, '[{"name":"Afar","lat":11.1,"lng":40.6,"radiusKm":{"north":180,"east":170},"weight":1},{"name":"Omo–Turkana","lat":4.5,"lng":36.2,"radiusKm":{"north":200,"east":150},"weight":0.6},{"name":"Laetoli","lat":-3.2,"lng":35.3,"radiusKm":{"north":150,"east":150},"weight":0.6}]'::jsonb, 3900000, 3800000, 2950000, 80000, null, 'species', 0.45, 'high', 3850000, 'Fossils from Hadar, Dikika and Laetoli span roughly 3.85–2.95 million years ago. Range drawn around the main fossil localities.', null),
  ('boisei-east-africa', 15, 'paranthropus-boisei', 'East Africa (Paranthropus boisei)', 2, 36.5, '[{"name":"Lake Turkana","lat":3.6,"lng":36.2,"radiusKm":{"north":220,"east":140},"weight":1},{"name":"Konso","lat":5.3,"lng":37.4,"radiusKm":{"north":110,"east":110},"weight":0.4},{"name":"Olduvai","lat":-3,"lng":35.4,"radiusKm":{"north":150,"east":150},"weight":0.7}]'::jsonb, 2350000, 2270000, 1200000, 80000, null, 'species', 0.42, 'high', 2300000, 'Fossils from East African sites span roughly 2.3–1.2 million years ago.', null),
  ('habilis-east-africa', 16, 'homo-habilis', 'East Africa (Homo habilis)', 1, 36.5, '[{"name":"Koobi Fora","lat":3.9,"lng":36.3,"radiusKm":{"north":180,"east":130},"weight":1},{"name":"Olduvai","lat":-3,"lng":35.3,"radiusKm":{"north":160,"east":160},"weight":0.8},{"name":"Afar","lat":11.1,"lng":40.5,"radiusKm":{"north":140,"east":140},"weight":0.35}]'::jsonb, 2450000, 2350000, 1400000, 100000, null, 'species', 0.42, 'medium', 2350000, 'Fossils attributed to H. habilis span roughly 2.4–1.4 million years ago; which specimens belong to the species is debated.', null),
  ('erectus-africa', 17, 'homo-erectus', 'Africa (Homo erectus)', 2, 37, '[{"name":"Turkana basin","lat":3.5,"lng":36,"radiusKm":{"north":250,"east":170},"weight":1},{"name":"Ethiopian Rift","lat":8.5,"lng":39.5,"radiusKm":{"north":220,"east":180},"weight":0.6},{"name":"Olduvai","lat":-3,"lng":35.3,"radiusKm":{"north":170,"east":170},"weight":0.5}]'::jsonb, 1950000, 1850000, 800000, 150000, null, 'species', 0.5, 'medium', 1900000, 'Early African H. erectus (sometimes called H. ergaster) from ~1.9 million years ago. The fade reflects changing fossil attributions in the Middle Pleistocene, not a known extinction.', null),
  ('erectus-dmanisi', 18, 'homo-erectus', 'Dmanisi, Georgia (early Homo)', 41.34, 44.34, '[{"name":"Mashavera valley","lat":41.34,"lng":44.34,"radiusKm":{"north":70,"east":90},"weight":1},{"name":"Kvemo Kartli","lat":41.45,"lng":44.6,"radiusKm":{"north":60,"east":90},"weight":0.4}]'::jsonb, 1870000, 1840000, 1760000, 30000, null, 'species', 0.3, 'high', 1850000, 'Fossils and tools at Dmanisi date to ~1.85–1.78 million years ago. Only this site is known, so the population is drawn small and brief. These are early Homo, not Homo sapiens.', null),
  ('erectus-china', 19, 'homo-erectus', 'China (Homo erectus)', 36, 112, '[{"name":"Loess Plateau (Lantian)","lat":34.2,"lng":109.5,"radiusKm":{"north":220,"east":320},"weight":1},{"name":"Zhoukoudian","lat":39.7,"lng":115.9,"radiusKm":{"north":160,"east":220},"weight":0.7},{"name":"Han River","lat":32.8,"lng":110.8,"radiusKm":{"north":150,"east":200},"weight":0.4}]'::jsonb, 1700000, 1600000, 350000, 80000, null, 'species', 0.5, 'medium', 1630000, 'Fossils from ~1.6 million years ago (Gongwangling) to roughly 400,000 years ago (e.g. Zhoukoudian, Hexian). Stone tools ~2.1 million years old show earlier hominins of unknown species.', null),
  ('erectus-java', 20, 'homo-erectus', 'Java (Homo erectus)', -7.4, 111.3, '[{"name":"Sangiran","lat":-7.45,"lng":110.83,"radiusKm":{"north":90,"east":160},"weight":1},{"name":"Solo River (Trinil, Ngandong)","lat":-7.37,"lng":111.5,"radiusKm":{"north":80,"east":180},"weight":0.8},{"name":"Mojokerto","lat":-7.4,"lng":112.4,"radiusKm":{"north":70,"east":110},"weight":0.35}]'::jsonb, 1500000, 1300000, 108000, 30000, null, 'species', 0.42, 'high', 1300000, 'From ~1.3 million years ago (Sangiran) to the youngest known H. erectus at Ngandong, ~117,000–108,000 years ago.', null),
  ('floresiensis-flores', 21, 'homo-floresiensis', 'Flores (Homo floresiensis)', -8.6, 120.8, '[{"name":"Liang Bua","lat":-8.53,"lng":120.46,"radiusKm":{"north":40,"east":70},"weight":1},{"name":"So''a Basin (Mata Menge)","lat":-8.69,"lng":121.1,"radiusKm":{"north":40,"east":70},"weight":0.8}]'::jsonb, 720000, 700000, 50000, 10000, null, 'species', 0.25, 'medium', 700000, 'H. floresiensis-like fossils at Mata Menge (~700,000 years ago) and skeletons at Liang Bua (~100,000–60,000); continuity between them is inferred. Tools show hominins on Flores by ~1 million years ago.', null),
  ('naledi-rising-star', 22, 'homo-naledi', 'Rising Star (Homo naledi)', -25.92, 27.71, '[{"name":"Cradle of Humankind","lat":-25.92,"lng":27.71,"radiusKm":{"north":70,"east":90},"weight":1}]'::jsonb, 345000, 335000, 236000, 10000, null, 'species', 0.22, 'medium', 335000, 'Known only from the Rising Star cave system (~335,000–236,000 years ago). The true range of the species is unknown; only the find area is drawn.', null),
  ('neanderthal-europe', 23, 'homo-neanderthalensis', 'Europe (Neanderthals)', 45, 8, '[{"name":"Iberia","lat":40.5,"lng":-4,"radiusKm":{"north":250,"east":320},"weight":0.6},{"name":"France","lat":45.5,"lng":2,"radiusKm":{"north":280,"east":320},"weight":1},{"name":"Central Europe","lat":49.5,"lng":11,"radiusKm":{"north":200,"east":380},"weight":0.7},{"name":"Italy","lat":42.5,"lng":13,"radiusKm":{"north":250,"east":110},"weight":0.4},{"name":"Balkans","lat":43,"lng":22,"radiusKm":{"north":200,"east":260},"weight":0.5},{"name":"Crimea","lat":44.9,"lng":34.2,"radiusKm":{"north":80,"east":140},"weight":0.2}]'::jsonb, 430000, 380000, 40000, 6000, null, 'species', 0.75, 'high', 430000, 'Neanderthal-lineage fossils from ~430,000 years ago (Sima de los Huesos); classic Neanderthals later. They disappear from the European record ~41,000–39,000 years ago.', null),
  ('neanderthal-west-asia', 24, 'homo-neanderthalensis', 'Western Asia & Caucasus (Neanderthals)', 37, 40, '[{"name":"Levant","lat":32.8,"lng":35.3,"radiusKm":{"north":150,"east":80},"weight":0.7},{"name":"Zagros (Shanidar)","lat":36.8,"lng":44.2,"radiusKm":{"north":160,"east":180},"weight":0.6},{"name":"Caucasus","lat":43,"lng":42.5,"radiusKm":{"north":120,"east":280},"weight":0.6}]'::jsonb, 160000, 120000, 42000, 8000, null, 'species', 0.5, 'medium', 120000, 'Neanderthal fossils and Middle Palaeolithic sites in the Levant (e.g. Tabun, Kebara), the Zagros (Shanidar) and the Caucasus. In the southern Caucasus, Middle Palaeolithic occupation ends around 40,000 years ago, before Upper Palaeolithic Homo sapiens are established there.', null),
  ('neanderthal-altai', 25, 'homo-neanderthalensis', 'Central Asia & Altai (Neanderthals)', 48, 78, '[{"name":"Altai","lat":51.4,"lng":84,"radiusKm":{"north":160,"east":280},"weight":1},{"name":"Teshik-Tash","lat":38.3,"lng":67.1,"radiusKm":{"north":120,"east":150},"weight":0.4}]'::jsonb, 135000, 120000, 45000, 8000, null, 'species', 0.35, 'medium', 120000, 'Neanderthal remains and DNA from the Altai (Denisova, Okladnikov and Chagyrskaya caves) and Teshik-Tash (Uzbekistan).', null),
  ('denisovan-altai', 26, 'denisovans', 'Altai (Denisovans)', 51.4, 84.7, '[{"name":"Denisova Cave","lat":51.4,"lng":84.7,"radiusKm":{"north":90,"east":150},"weight":1}]'::jsonb, 210000, 195000, 50000, 8000, null, 'species', 0.28, 'high', 195000, 'Denisovan fossils and sediment DNA at Denisova Cave span roughly 200,000–50,000 years ago.', null),
  ('denisovan-tibet', 27, 'denisovans', 'Tibetan Plateau (Denisovans)', 35.45, 102.57, '[{"name":"Baishiya Karst","lat":35.45,"lng":102.57,"radiusKm":{"north":110,"east":170},"weight":1}]'::jsonb, 170000, 160000, 50000, 10000, null, 'species', 0.25, 'medium', 160000, 'The Xiahe mandible (≥160,000 years ago); sediment DNA suggests Denisovans used the cave much later as well. Genetic evidence implies a far wider, unmapped range across Asia, which is not drawn.', null),
  ('luzonensis-luzon', 28, 'homo-luzonensis', 'Luzon (Homo luzonensis)', 17.7, 121.8, '[{"name":"Callao Cave","lat":17.7,"lng":121.82,"radiusKm":{"north":60,"east":40},"weight":1}]'::jsonb, 70000, 67000, 50000, 3000, null, 'species', 0.15, 'medium', 67000, 'Homo luzonensis fossils at Callao Cave have minimum ages of ~67,000 and ~50,000 years. Earlier tools on Luzon (~709,000 years) have no fossils.', null);
