insert into public.milestones (id, sort_order, title, category, approximate_start_bp, approximate_end_bp, date_label, lat, lng, location_label, location_approximate, short_description, detailed_description, evidence, origin_note, significance, evidence_type, confidence, visual_icon, animation_type) values
  ('lomekwi-tools', 0, 'The oldest known stone tools', 'stone-tools', 3300000, null, '~3.3 million years ago', 3.95, 35.85, 'Lomekwi 3, West Turkana, Kenya', true, 'Large stone cores and flakes, made before the earliest known fossils of the genus Homo.', 'At Lomekwi 3, flakes were struck from heavy cobbles by hammering them against an anvil or with a hand-held stone. The tools are about 700,000 years older than the previously known oldest tools.', 'Stone cores, flakes and anvils excavated from sediments dated to ~3.3 million years ago.', 'The maker is unknown: no hominin fossils were found with the tools, and they predate the earliest known Homo. Australopithecus and Kenyanthropus are candidates. Some researchers question the context of the finds.', 'Toolmaking did not begin with our genus. It shows that technology predates big brains.', 'archaeological', 'medium', 'stone-tool', 'rotate'),
  ('oldowan', 1, 'Oldowan stone tools', 'stone-tools', 2600000, null, '~2.6 million years ago', 11.05, 40.3, 'Gona, Afar, Ethiopia', true, 'Simple, sharp flakes struck from cobbles: a toolkit that lasted for more than a million years.', 'Oldowan tools, named after Olduvai Gorge, were used to cut meat from carcasses and process plants. The well-dated artefacts at Gona are among the earliest; Nyayanga in Kenya has Oldowan tools from ~3.0–2.6 million years ago.', 'Cores and flakes from dated sediments at Gona; butchered animal bones at later sites.', 'Often credited to early Homo, but Paranthropus teeth occur with some of the earliest Oldowan tools, so who made them is uncertain.', 'Opened up meat and marrow as food sources and set the pattern of tool dependence that defines later hominins.', 'archaeological', 'high', 'stone-tool', 'rotate'),
  ('acheulean', 2, 'The first handaxes (Acheulean)', 'stone-tools', 1760000, null, '~1.76 million years ago', 4.05, 35.78, 'Kokiselei 4, West Turkana, Kenya', true, 'Symmetrical tools shaped on both faces: the first designed standard form.', 'Acheulean handaxes and cleavers required planning a shape in advance. The tradition spread across Africa and western Eurasia and lasted for more than a million years.', 'Handaxes and picks from sediments dated to ~1.76 million years ago.', 'Generally linked to Homo erectus because of its age and distribution, but no fossils were found at Kokiselei itself.', 'A long-lived standard design suggests skills passed on by teaching or imitation across countless generations.', 'archaeological', 'high', 'handaxe', 'rotate'),
  ('fire', 3, 'Earliest evidence of fire use', 'fire', 1000000, null, '~1 million years ago', -27.85, 23.55, 'Wonderwerk Cave, South Africa', null, 'Burned bone and plant ash in a cave, among the earliest secure traces of fire used by hominins.', 'Microscopic study of Acheulean layers at Wonderwerk Cave found ash and burned bone that were burned inside the cave, not carried in by wildfires. At Gesher Benot Ya''aqov in Israel (~780,000 years ago), burned seeds, wood and flint cluster in hearth-like patches.', 'Ashed plant remains and burned bone in their original position (Wonderwerk); spatial clusters of burned material (Gesher Benot Ya''aqov).', 'Earliest secure evidence, not the origin. Older claims (~1.5 million years ago in Kenya) are debated, and habitual, everyday fire use becomes clear only after ~400,000 years ago. No hominin fossils were found with the Wonderwerk ash.', 'Fire brought warmth, protection, light and cooking, which makes food easier to digest.', 'archaeological', 'medium', 'fire', 'flicker'),
  ('schoningen-spears', 4, 'Wooden hunting spears', 'hunting-gathering', 300000, 200000, '~300,000 years ago (age under revision)', 52.14, 10.98, 'Schöningen, Germany', null, 'Carefully shaped spruce and pine spears found with the butchered remains of horses.', 'Waterlogged lake-shore sediments preserved complete wooden spears up to ~2.5 m long, balanced like modern javelins, together with the remains of more than 20 horses.', 'Wooden spears and butchered horse bones from an ancient lake shore.', 'No hominin fossils were found; the makers were probably populations on the Neanderthal lineage, but that is an inference. Some recent studies argue for a younger age (~200,000 years ago).', 'Clear evidence of planned, cooperative big-game hunting with weapons made from wood, a material that rarely survives.', 'archaeological', 'medium', 'spear', 'draw'),
  ('blombos-engraving', 5, 'Abstract engravings and drawing', 'symbolic', 75000, 73000, '~75,000–73,000 years ago', -34.41, 21.22, 'Blombos Cave, South Africa', null, 'Ochre pieces engraved with cross-hatched lines, and a cross-hatched drawing made with an ochre crayon.', 'Middle Stone Age layers at Blombos contain engraved ochre (~75,000 years ago) and a stone flake with lines drawn in red ochre (~73,000 years ago), along with shell beads.', 'Engraved ochre, a drawn pattern on silcrete and perforated shell beads in dated layers that also contain Homo sapiens teeth.', 'Among the earliest well-dated examples, not the origin. A shell engraved ~500,000 years ago from Trinil (Java), attributed to Homo erectus, suggests that pattern-making may be much older.', 'Deliberate abstract patterns are widely read as evidence of symbolic thinking.', 'archaeological', 'high', 'engraving', 'draw'),
  ('iberian-art-neanderthal', 6, 'Possible Neanderthal cave art (debated)', 'symbolic', 64000, null, '≥64,000 years ago (contested)', 43.28, -3.97, 'La Pasiega, Cantabria, Spain', null, 'Red pigment marks dated to before Homo sapiens reached Iberia, which would make Neanderthals the artists.', 'Uranium–thorium dating of mineral crusts over red marks in three Spanish caves produced minimum ages of more than 64,000 years. If correct, Neanderthals made them.', 'U–Th dates on carbonate crusts overlying pigment.', 'Other researchers dispute the dating method and whether the marks are deliberate art. Treat as an open question.', 'If confirmed, it would show symbolic behaviour in a second human species.', 'archaeological', 'low', 'cave-art', 'draw'),
  ('kebara-hyoid', 7, 'A Neanderthal hyoid bone', 'language', 60000, null, '~60,000 years ago', 32.558, 34.937, 'Kebara Cave, Israel', null, 'The small throat bone that anchors the tongue, closely resembling ours.', 'The Kebara 2 Neanderthal skeleton preserved a hyoid bone whose shape is very similar to that of modern humans.', 'A fossil hyoid bone from a Neanderthal burial.', 'Language leaves no direct trace. This shows that anatomy compatible with speech existed, not that Neanderthals had language like ours; the question remains open.', 'One of the few fossil clues bearing on when the capacity for speech evolved.', 'fossil', 'low', 'voice', 'glow'),
  ('sulawesi-cave-art', 8, 'The oldest known figurative cave art', 'symbolic', 51200, null, '≥51,200 years ago (minimum age)', -4.95, 119.65, 'Leang Karampuang, Sulawesi, Indonesia', true, 'A painted scene of human-like figures interacting with a pig.', 'Laser-ablation uranium-series dating of mineral deposits over the paint gave a minimum age of 51,200 years for this narrative scene in a limestone cave of southern Sulawesi.', 'Red pigment painting with dated mineral crusts above it.', 'A minimum age: the painting is at least this old. Attributed to Homo sapiens on the basis of its date and region; no human remains were found with it.', 'Shows storytelling art in Southeast Asia earlier than the famous European caves, during the spread of Homo sapiens towards Sahul.', 'archaeological', 'medium', 'cave-art', 'draw'),
  ('sahul-seafaring', 9, 'Open-sea crossings to Sahul', 'seafaring', 50000, 47000, 'by ~50,000–47,000 years ago', -10.5, 127, 'Timor Sea crossing (Wallacea to Sahul)', true, 'Even at the lowest Ice Age sea levels, reaching Australia–New Guinea required crossing open water.', 'Sahul was never connected to mainland Asia. People arriving there had to cross a chain of sea gaps, some wide enough that land on the other side was not visible.', 'Archaeological sites in Sahul from ~50,000–47,000 years ago (with a debated older date at Madjedbebe).', 'No boats survive; seafaring is inferred from people arriving on islands. Earlier hominins reached Flores by ~1 million years ago, possibly by accident rather than deliberate voyaging.', 'Among the earliest evidence of deliberate sea crossings, and part of the Southeast Asia → Sahul route.', 'archaeological', 'high', 'boat', 'drift'),
  ('dzudzuana-flax', 10, 'Dyed flax fibres in Georgia', 'clothing', 36000, 26000, '~36,000–26,000 years ago (often cited as ~30,000)', 42.31, 43.27, 'Dzudzuana Cave, Imereti, Georgia', null, 'Wild flax fibres, some twisted and dyed, preserved in an Upper Palaeolithic cave.', 'Microscopic analysis of cave sediments at Dzudzuana found hundreds of flax fibres. Some were twisted into threads and some were coloured (black, grey, turquoise and pink), suggesting cords, baskets or textiles.', 'Microscopic wild flax fibres in Upper Palaeolithic layers of a Georgian cave.', 'Fibres show the use of plant materials; the objects themselves do not survive. Sewing with needles is attested elsewhere in Eurasia in roughly the same era.', 'Among the oldest evidence of fibre technology in the world: a reminder that most early technology was perishable.', 'archaeological', 'medium', 'needle', 'draw'),
  ('xianrendong-pottery', 11, 'The earliest known pottery', 'pottery', 20000, null, '~20,000 years ago', 28.72, 117.17, 'Xianrendong Cave, Jiangxi, China', null, 'Fragments of fired clay vessels made by hunter-gatherers during the last Ice Age.', 'Pottery sherds from Xianrendong are dated by radiocarbon to ~20,000 years ago, about 10,000 years before farming began in the region.', 'Pottery sherds in dated cave layers.', 'Pottery did not come with farming: it began among East Asian hunter-gatherers and arose independently in other regions later.', 'Cooking in containers, possibly to extract fat and nutrients from food in a cold climate.', 'archaeological', 'high', 'pottery', 'rotate'),
  ('bonn-oberkassel-dog', 12, 'Dogs: the first domestic animal', 'domestication', 14200, null, '~14,200 years ago', 50.71, 7.17, 'Bonn-Oberkassel, Germany', null, 'A young dog buried with two people, which had been cared for through a serious illness.', 'The Oberkassel dog had canine distemper and would probably have needed human care to survive for weeks, suggesting an emotional bond rather than just a working animal.', 'A dog skeleton from a human burial dated to ~14,200 years ago.', 'Among the earliest generally accepted domestic dogs; genetic studies suggest domestication from wolves began earlier, and where it happened is debated.', 'The first animal domesticated, by hunter-gatherers, thousands of years before farming.', 'archaeological', 'high', 'animal', 'glow'),
  ('near-east-agriculture', 13, 'Farming in the Fertile Crescent', 'agriculture', 11500, 10000, '~11,500–10,000 years ago (~9500–8000 BCE)', 37.3, 39.5, 'Northern Fertile Crescent (southeastern Anatolia and the Levant)', true, 'Wheat, barley, lentils and peas were cultivated and gradually domesticated.', 'Cultivation of wild cereals and legumes led, over centuries, to domesticated forms whose seeds no longer scatter naturally. Farming villages spread across the region and later into Europe, Africa and Asia.', 'Plant remains showing domestication traits, and changes in settlement and tools.', 'One of several independent origins: farming also arose in China, New Guinea, Mesoamerica, the Andes, eastern North America and Africa. Cultivation began before crops looked domesticated, so there is no single ''invention'' moment.', 'Food production supported larger, settled communities and transformed landscapes, diets and societies.', 'archaeological', 'high', 'sprout', 'grow'),
  ('zagros-goats', 14, 'Goat herding in the Zagros', 'domestication', 10000, null, '~10,000 years ago (~8000 BCE)', 34.3, 47.5, 'Ganj Dareh, Zagros Mountains, Iran', true, 'Herd management of goats shows up in the age and sex of slaughtered animals.', 'At Ganj Dareh, young males were culled while females were kept to breed: a herding strategy that appears before goat bones change shape through domestication.', 'Age and sex profiles of goat remains from a dated Neolithic village.', 'Sheep, cattle and pigs were domesticated in the same broad region and period; other animals were domesticated independently elsewhere.', 'Livestock provided meat, milk, hides and later wool and traction.', 'archaeological', 'high', 'herd', 'glow'),
  ('catalhoyuk', 15, 'A large Neolithic town: Çatalhöyük', 'settlement', 9100, 8000, '~7100–6000 BCE (~9,100–8,000 years ago)', 37.67, 32.83, 'Çatalhöyük, Konya Plain, Türkiye', null, 'Thousands of people living in tightly packed mud-brick houses entered through the roof.', 'Çatalhöyük had no streets: houses were built against each other and rebuilt over centuries. Wall paintings, plastered bulls'' horns and burials under the floors fill its rooms.', 'Excavated houses, art and burials spanning more than a thousand years.', 'Not the first settlement (permanent villages are older in the Levant), but one of the largest and best studied of the Neolithic.', 'Shows how people organised life in large farming communities before cities with central institutions.', 'archaeological', 'high', 'settlement', 'glow'),
  ('gadachrili-wine', 16, 'The earliest known grape wine', 'wine', 8000, 7800, '~6000–5800 BCE (~8,000 years ago)', 41.43, 44.74, 'Gadachrili Gora, Kvemo Kartli, Georgia', true, 'Chemical traces of grape wine in Neolithic jars from southern Georgia.', 'Residue analysis of pottery from Gadachrili Gora and nearby Shulaveris Gora detected tartaric acid and related acids, the chemical fingerprint of grape wine. Grape pollen and starch from the site point to local grapevines.', 'Organic residues in early Neolithic pottery (Shulaveri–Shomutepe culture) from two villages, with radiocarbon dates.', 'Earliest chemical evidence of grape wine, not proof that wine was invented here. Older fermented drinks of other ingredients are known elsewhere (e.g. at Jiahu, China). This is a local Neolithic development, not a result of any migration shown on this globe.', 'A cornerstone of Georgia''s cultural heritage: traditional winemaking in clay qvevri vessels is recognised by UNESCO as Intangible Cultural Heritage (2013).', 'archaeological', 'high', 'wine', 'pour'),
  ('belovode-copper', 17, 'Copper smelting', 'metallurgy', 7000, null, '~5000 BCE (~7,000 years ago)', 44.27, 21.53, 'Belovode, Serbia', null, 'Copper extracted from ore with fire, rather than hammered from native metal.', 'Slag, ore and copper droplets at Belovode (Vinča culture) show that copper was smelted from minerals by ~5000 BCE.', 'Smelting slag and metal droplets in dated layers.', 'Earliest securely dated smelting; native copper had been hammered into small objects in Anatolia and the Near East thousands of years earlier, and metallurgy may have developed in more than one place.', 'The start of extractive metallurgy, leading to bronze and iron.', 'archaeological', 'high', 'metal', 'glow'),
  ('uruk-city', 18, 'Early cities: Uruk', 'settlement', 6000, 5000, '~4000–3000 BCE', 31.32, 45.64, 'Uruk, southern Mesopotamia (Iraq)', null, 'One of the world''s first cities, with monumental temples and tens of thousands of inhabitants.', 'During the 4th millennium BCE Uruk grew into a city covering several square kilometres, with specialised crafts, administration and long-distance exchange.', 'Excavated monumental architecture, administrative objects and settlement surveys.', 'Cities emerged independently in several regions over the following millennia, for example in Egypt, the Indus Valley, China and the Americas.', 'Urban life brought new forms of power, labour, record-keeping and inequality.', 'archaeological', 'high', 'settlement', 'glow'),
  ('uruk-writing', 19, 'Writing', 'writing', 5300, 5100, '~3300–3100 BCE (~5,200 years ago)', 31.32, 45.64, 'Uruk, southern Mesopotamia (Iraq)', null, 'Proto-cuneiform signs pressed into clay tablets to record goods and labour.', 'The earliest Uruk tablets are administrative accounts. Over centuries the signs developed into cuneiform, which could record full language.', 'Clay tablets from dated layers at Uruk.', 'Writing was invented independently at least in Mesopotamia, Egypt (~3200 BCE), China (by ~1200 BCE) and Mesoamerica.', 'Information could now be stored outside human memory, making the historical record possible.', 'archaeological', 'high', 'writing', 'draw'),
  ('gby-cooking', 20, 'Earliest evidence of cooking', 'fire', 780000, null, '~780,000 years ago', 33, 35.63, 'Gesher Benot Ya''aqov, Jordan Valley, Israel', null, 'Fish teeth altered by moderate heat, clustered around ancient hearths.', 'Teeth of large carp from a lake-shore Acheulean site show changes in their crystal structure produced by heating at temperatures typical of cooking (below ~500 °C) rather than burning. They concentrate in areas where earlier studies identified hearths.', 'Heat-altered fish teeth and burned material in the same layers as Acheulean tools.', 'Among the earliest direct archaeological evidence of cooking, not its origin: it has been argued on biological grounds that cooking began earlier, but direct evidence is lacking. No hominin fossils were found at the site; the makers of its Acheulean tools are not identified.', 'Cooking makes food easier to chew and digest, and controlled fire made it possible.', 'archaeological', 'medium', 'cooking', 'glow'),
  ('shell-beads', 21, 'Shell beads: early ornaments', 'symbolic', 82000, null, '~82,000 years ago (possibly older at Skhul)', 34.81, -2.41, 'Grotte des Pigeons (Taforalt), Morocco', null, 'Perforated Nassarius shells, some stained with red ochre, worn as beads.', 'Small marine shells with deliberate perforations, use-wear from stringing and traces of ochre come from well-dated Middle Stone Age layers at Taforalt. Similar beads are known from Skhul (Israel) and Oued Djebbana (Algeria), and later from Blombos Cave.', 'Perforated, ochre-stained shells carried tens of kilometres inland from the coast.', 'Earliest well-dated examples, not the origin. Beads from Skhul may be older (~100,000–135,000 years), but their context is debated. Attribution to Homo sapiens rests on the fossils of the North African Middle Stone Age; no remains were found with these beads.', 'Personal ornaments signal identity and social relationships, a strong marker of symbolic behaviour.', 'archaeological', 'high', 'ornament', 'drift'),
  ('chauvet', 22, 'Chauvet Cave paintings', 'symbolic', 36500, 28000, '~37,000–33,500 and ~31,000–28,000 years ago (two phases)', 44.389, 4.416, 'Chauvet-Pont d''Arc, Ardèche, France', null, 'Hundreds of animals painted and engraved with shading and perspective.', 'Lions, horses, rhinoceroses and mammoths cover the walls of a cave sealed by a rockfall. A model based on hundreds of radiocarbon dates places human activity in two phases, the first around 37,000–33,500 years ago.', 'Radiocarbon dates on charcoal, bones and pigment, combined in a chronological model.', 'Not the oldest art (Sulawesi and the Blombos engravings are older), but one of the oldest and most accomplished painted caves in Europe.', 'Shows sophisticated visual art by Upper Palaeolithic Homo sapiens soon after their arrival in western Europe.', 'archaeological', 'high', 'cave-art', 'draw'),
  ('natufian-villages', 23, 'The first permanent villages', 'settlement', 15000, 11700, '~15,000–11,700 years ago', 33.08, 35.59, 'Ain Mallaha (Eynan), Hula Valley, Israel', null, 'Natufian hunter-gatherers built round stone houses and stayed year-round, before farming.', 'Natufian sites in the Levant have stone-built houses, cemeteries, storage and grinding tools for wild cereals. People lived in one place for long periods while still hunting and gathering.', 'Architecture, burials and grinding equipment from excavated Natufian settlements.', 'Sedentary life developed gradually and preceded farming; earlier sites (e.g. Ohalo II, ~23,000 years ago) show long stays. Permanent villages also arose independently elsewhere.', 'Living in one place changed social life and set the stage for cultivation in the same region.', 'archaeological', 'high', 'settlement', 'glow');
